quests[9942] = { id = 9942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Down the Culprits", description = "The arakkoa tracks, accompanied by a pair of shallow ruts, lead north across the road. It seems the arakkoa dragged something away from the site of the battle, perhaps toward a nearby settlement.\n\nWhile the broken cart shows signs of a struggle, there's little information about Dugar's fate. Follow the arakkoa tracks north and continue your search for the merchant. If he was captured alive, there may still be a chance to rescue him.", sourceObjective = "Continue your search for signs of Dugar in the Arakkoa settlement north of the broken cart.", sourceObjectiveStatus = "unverified-source-field" }
quests[9943] = { id = 9943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Thander", description = "Deirom's cargo doesn't seem to have been harmed or even opened. The cargo clearly seemed of interest to them, but it seems their prisoner was more important. What the arakkoa hoped to gain from attacking and kidnapping Deirom remains unclear, but the merchant is certainly not being held here. \n\nWithout any further clues as to how to continue your search, you decide it might be a good time to report your findings to Thander.", sourceObjective = "Return to Thander at the Allerian Stronghold with news of your findings.", sourceObjectiveStatus = "unverified-source-field" }
quests[9944] = { id = 9944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Mag'hari Procession", description = "Greatmother says that we must press on and serve our people. She says that we must serve as an example for Garrosh - to show that life goes on.\n\nI have so many matters to attend to here, especially with Greatmother having taken ill. Would you honor the Mag'har by helping one of their matrons?\n\nSeveral days ago we sent a funeral procession to the Ancestral Grounds and they have yet to return. Will you go search for them? They took the western road out of Garadar. Follow it around and avoid Halaa.", completion = "Thirty orcs, {race}! Of those original thirty, only Ungriz and I remain. We found the young orc, Saurfang, nearly dead near Sunspring. Apparently he was here for another reason...", objectives = "Search for the missing Mag'hari procession.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9945] = { id = 9945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War on the Warmaul", description = "We were en route to the Ancestral Grounds when we were ambushed by Warmaul. They came from all sides, killing several of the procession guards and many of the others. They even desecrated the remains of the elder in the wagon.\n\nAnd for what? So they could humiliate us and display their power. Not even Boulderfist would have sunk so low.\n\nI am a spiritual orc, {name}, but even I have limitations. Find the attackers at Warmaul Hill to the northwest and destroy them!", completion = "It is a good start, but their leader must be dealt with for your actions to have any lasting impact.", objectives = "Elder Yorley at the Mag'hari Procession in Nagrand has asked that you slay 8 Warmaul Brutes and 8 Warmaul Warlocks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9946] = { id = 9946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cho'war the Pillager", description = "Have you ever seen an ogre king, {race}? Few have and lived to tell the tale. Unfortunately, that is exactly what we are dealing with here.\n\nThe leader of these barbarians is an ogre named Cho'war. Rumor has it that Cho'war was the ogre responsible for forcing the gronn out of the cave. Cho'war then declared himself king and dissolved the ogre clans that served under the gronn. Thus, Warmaul was born.\n\nFind Cho'war deep in the caves of Warmaul Hill. Slay him and bring me his head.", progress = "He will undoubtedly be heavily guarded.", completion = "This head will be posted at the gates of Garadar for all to see. The ogres will think twice before interrupting sacred Mag'hari rituals.", objectives = "Elder Yorley at the Mag'hari Procession in Nagrand has asked that you slay Cho'war the Pillager and retrieve the Head of Cho'war.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9947] = { id = 9947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Rokag", description = "Dugar's cargo doesn't seem to have been harmed or even opened. The cargo clearly seemed of interest to them, but it seems their prisoner was more important. What the arakkoa hoped to gain from attacking and kidnapping Dugar remains unclear, but the merchant is certainly not being held here. \n\nWithout any further clues as to how to continue your search, you decide it might be a good time to report your findings to Rokag.", sourceObjective = "Return to Rokag at Stonebreaker Hold with news of your findings.", sourceObjectiveStatus = "unverified-source-field" }
quests[9948] = { id = 9948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding the Survivors", description = "If I know anything about ogres, it's that they like their food fresh. This means that the Mag'har that they captured are more than likely being kept alive until they are ready to serve. It's a sickening thought, I know, but one that we must use to our advantage.\n\nVenture to Warmaul Hill and search for Mag'har prisoners. If you find prisoners, then you will find keys to their cages on the nearby Warmaul ogres.\n\nKill ogres for their keys and release the prisoners.", completion = "You have done what none thought was possible and brought back our missing brothers and sisters. You are a hero to the Mag'har, {name}. All will know your name and the deeds that you have performed for us.", objectives = "Elder Ungriz at the Mag'hari Procession in Nagrand has asked that you free 5 Mag'har Prisoners.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9949] = { id = 9949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bird's-Eye View", description = "With no further information to go on, we're in a difficult situation. I'm not going to give up on finding and rescuing Deirom. His abduction isn't an accident, {name}.\n\nThe arakkoa are up to something, but what is it they're planning?\n\nAndarl, over in the mage tower, knows something of their peculiar magic. With the right tools, he can scare up some new information for us. He'll need the \"eye\" crystals from each of the arakkoa towns north of the Bone Wastes - Veil Skith, Veil Reskk, and Veil Shienor.", objectives = "Bring the Eye of Veil Skith, the Eye of Veil Shienor, and the Eye of Veil Reskk to Andarl at the Allerian Stronghold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9950] = { id = 9950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bird's-Eye View", description = "With no further information to go on, we're in a difficult situation. I'm not going to give up on finding and rescuing Dugar. His abduction isn't an accident, {name}.\n\nThe arakkoa are up to something, but what is it they're planning?\n\nKurgatok the warlock knows something of their peculiar magic. With the right tools, he can scare up some new information for us. He'll need the \"eye\" crystals from each of the arakkoa towns north of the Bone Wastes - Veil Skith, Veil Reskk, and Veil Shienor.", objectives = "Bring the Eye of Veil Skith, the Eye of Veil Shienor, and the Eye of Veil Reskk to Kurgatok at Stonebreaker Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9951] = { id = 9951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Watching You!", description = "Quick, hide!  The eyes of Naphthal'ar are upon you... upon us all!\n\nI dare not go to the top of the tower to speak with it, but you... you look as if you might know the right words to say.  Just be careful, it doesn't like jokes and will not suffer fools easily.\n\nIf you can, convince it to come down for tea.  But, by all means, get it to stop staring at me!", progress = "We should never have invited them to dinner.  That much is certain!\n\nOr, at least, we should have insisted upon a couple of courses before the dessert that they brought.", completion = "It's for the best, really.  If it cannot civilly accept an invitation then it has no business attending.\n\n<Warden Treelos looks momentarily confused.>\n\nWho are you and what are you doing here?  You must get out of here quickly before it is too late!", objectives = "Kill Naphthal'ar and then return to Warden Treelos at the Cenarion Thicket in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9952] = { id = 9952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prospector Balmoral", description = "So Andarl is certain Deirom is being held in Veil Shalas? That's the largest of the arakkoa settlements that we know of.\n\nVeil Shalas is in the far south of the forest, close to the eastern rim of the Bone Wastes. Unfortunately, I don't have much information on it, but there is an Explorers' League member camped down there who may be able to help you. Prospector Balmoral's camp is perched on the very edge of the land to the southwest of Veil Shalas. Consult him before making any move against the arakkoa.", sourceObjective = "Locate and speak with Prospector Balmoral.", sourceObjectiveStatus = "unverified-source-field" }
quests[9953] = { id = 9953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lookout Nodak", description = "So Kurgatok is certain Dugar is being held in Veil Shalas? That's the largest of the arakkoa settlements that we know of.\n\nVeil Shalas is in the far south of the forest, close to the eastern rim of the Bone Wastes. Unfortunately, I don't have much information on it, but we have a scout camped down there who may be able to help you. Lookout Nodak's camp is perched on the very edge of the land to the southwest of Veil Shalas. Consult him before making any move against the arakkoa.", sourceObjective = "Locate and speak with Lookout Nodak.", sourceObjectiveStatus = "unverified-source-field" }
quests[9954] = { id = 9954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corki's Ransom", description = "<Arechron shows you a grime covered letter.>\n\nI just received this letter. It's from a clan of ogres known as Warmaul that rule the northwestern lands of Nagrand. It says that they have Corki and if we don't cooperate, they're going to eat him. Admittedly, Corki is a moron, but he's still my blood. Will you rescue him, {name}?\n\nI presume that he's locked up in a cage somewhere on Warmaul Hill. That should be your first stop.", completion = "They've got me locked up good this time, {name}. The Warmaul king, Cho'war, has the key.", objectives = "Arechron wants you to find Corki at Warmaul Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9955] = { id = 9955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cho'war the Pillager", description = "They call him Cho'war the Pillager, {name}. He's the ogre that forced out the gronn that used to rule over these ogres. You better believe he's powerful!\n\nThe chef said that Cho'war lives in the big cave - wherever that may be... Get that key and get me out of here! If we live through this, my father will no doubt give you the big reward! As soon as I'm free, seek him out.", completion = "Thank you, {name}. Corki's been sent away to live among the night elves in Blade's Edge. Hopefully they'll be able to keep him out of trouble.\n\nAbout that reward...", objectives = "Corki wants you to get Cho'war's Key so that you can free him from his cage. Return to Arechron at Telaar should you manage this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9956] = { id = 9956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ravaged Caravan", description = "I was part of a caravan taking supplies to the Orebor Harborage in Zangarmarsh. As we were nearing the border of the marsh, we were jumped by a vicious squad of Warmaul ogres. They killed the others and took me prisoner, along with all of our supplies.\n\nThankfully, they neglected to place a backing on my cage. When they fell asleep, I made my escape.\n\nIt's too late for my comrades but we could really use the supplies they stole. Warmaul Hill is in the northwestern mountains of Nagrand.", progress = "I feel so stupid. Arechron's son, Corki, asked me what happened and I told him. Now he's gone missing again!", completion = "Amazing! How did you manage to carry all of that back by yourself?", objectives = "Huntress Kima at Telaar in Nagrand wants you to recover 10 Telaar Supply Crates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9957] = { id = 9957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Wrong at Cenarion Thicket?", description = "We haven't heard from the druids at the Cenarion Thicket of Terokkar Forest in quite some time.\n\n{name}, I'd like for you to go down there and check in with them to see what's happening.  There are several ways to get there, but the fastest is to head south along the path, and then take the road that branches east from Shattrath City once you're in the forest.", completion = "I'm glad that the refuge sent you.  The druids of the thicket have been slain!  Only myself and one other have survived, and he's insane.\n\nI don't know what happened, but I intend to get to the bottom of it.  Whatever it was, it happened quickly and feels unnatural.\n\nWill you help me?", objectives = "Speak with one of the druids at the Cenarion Thicket in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9958] = { id = 9958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting the Defenses", description = "In my time out here, I've had a few interactions with the arakkoa, none of them friendly. They seem very territorial, but I suppose we're the same way, aren't we?\n\nThe arakkoa wield a kind of primal magic unknown to us on Azeroth and have used it to weave defenses for Veil Shalas. Before moving against them, it would be prudent to scout out their defenses so we know what we're up against.", objectives = "Approach Veil Shalas and observe the town's defenses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9959] = { id = 9959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting the Defenses", description = "In my time out here, I've had a few interactions with the arakkoa, none of them friendly. They seem very territorial, but I suppose we're the same way, aren't we? Not even the ancestors recorded any encounters with the bird-men.\n\nThe arakkoa wield a kind of primal magic unknown to our seers and have used it to weave defenses for Veil Shalas. Before moving against them, it would be wise to scout out their defenses so we know what we're up against.", objectives = "Approach Veil Shalas and learn about the magic defending the settlement.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9960] = { id = 9960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Wrong at Cenarion Thicket?", description = "Hey there, {class}.  We haven't heard from the druids of the Cenarion Thicket in quite some time.\n\nI want you to go over there and check to see what's happening.  You can find it by heading northwest through the forest.", completion = "I'm glad that Stonebreaker Hold sent you.  The druids of the thicket have been slain!  Only myself and one other have survived, and he's insane.\n\nI don't know what happened, but I intend to get to the bottom of it.  Whatever it was, it happened quickly and feels unnatural.\n\nWill you help me?", objectives = "Speak with one of the druids at the Cenarion Thicket in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9961] = { id = 9961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Wrong at Cenarion Thicket?", description = "{class}, I have urgent business for you.  We haven't heard from the druids of the Cenarion Thicket in quite some time.  This is unusual as we usually hear from them at least once every few days.\n\nI want you to go up there and make sure that they're alright.  You can find the thicket by heading northwest through the forest.", completion = "I'm glad that Allerian Stronghold sent you.  The druids of the thicket have been slain!  Only myself and one other have survived, and he's insane.\n\nI don't know what happened, but I intend to get to the bottom of it.  Whatever it was, it happened quickly and feels unnatural.\n\nWill you help me?", objectives = "Speak with one of the druids at the Cenarion Thicket in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9962] = { id = 9962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ring of Blood: Brokentoe", description = "So are you ready for your first battle? If you are, let me know and I'll get things started. All you have to do is go wait in the Ring of Blood for your opponent to arrive.\n\nThis fight is against Brokentoe, a ferocious clefthoof.\n\nGood luck! I hope you brought friends.\n\nAnd remember, the fight's over when either you or your opponent are lying face down on the arena floor.", progress = "The fight's over when you or your opponent are dead on the floor.", completion = "Hrm, not bad. Not bad at all... You've got potential, kid. Here's a little gold to line your pockets with...", objectives = "Defeat Brokentoe. Should you win, speak with Wodin the Troll-Servant to collect your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9963] = { id = 9963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Help from the Source", description = "The wards you encountered are powerful magic, indeed. The techniques employed by the arakkoa are so far beyond our understanding that we can only hope to find a counter with their help.\n\nI know what's going through your mind. Why would an enemy help us to overcome their defenses? The answer is that they wouldn't, of course. Have you heard the tales of a crazy old arakkoa sage named Kokorek? They say he's hiding in Veil Lithic on the western edge of the Bone Wastes, waiting for the return of a lost age.", sourceObjective = "Find Kokorek in Veil Lithic and speak with him.", sourceObjectiveStatus = "unverified-source-field" }
quests[9964] = { id = 9964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Help from the Source", description = "The wards you encountered are powerful magic, indeed. The techniques employed by the arakkoa are so far beyond our understanding that we can only hope to find a counter with their help.\n\nI know what's going through your mind. Why would an enemy help us to overcome their defenses? The answer is that they wouldn't, of course. Have you heard the tales of a crazy old arakkoa sage named Kokorek? They say he's hiding in Veil Lithic on the western edge of the Bone Wastes, waiting for the return of a lost age.", sourceObjective = "Find Kokorek in Veil Lithic and speak with him.", sourceObjectiveStatus = "unverified-source-field" }
quests[9965] = { id = 9965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Show of Good Faith", description = "I'd like to propose something of a trade: demonstrate your good intentions by helping me resolve a little problem, and I'll help you rescue your comrade.\n\nThe ogres are an ancient enemy of my people, and lately they have begun to filter back into our forest from the grasslands of Nagrand.\n\nOne particular ogre, Mug'gok, is quite an adventurous fellow, but none too bright. He goes back and forth between causing trouble for his friends at the Bleeding Hollow Ruins and trying to provoke us.", objectives = "Bring Mug'gok's Head to Kokorek in Veil Lithic.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9966] = { id = 9966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Show of Good Faith", description = "I'd like to propose something of a trade: demonstrate your good intentions by helping me resolve a little problem, and I'll help you rescue your comrade.\n\nThe ogres are an ancient enemy of my people, and lately they have begun to filter back into our forest from the grasslands of Nagrand.\n\nOne particular ogre, Mug'gok, is quite an adventurous fellow, but none too bright. He goes back and forth between causing trouble for his friends at the Bleeding Hollow Ruins and trying to provoke us.", objectives = "Bring Mug'gok's Head to Kokorek in Veil Lithic.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9967] = { id = 9967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ring of Blood: The Blue Brothers", description = "This next battle involves a duo - twin brothers to be precise. They call themselves the \"Blue Brothers.\"\n\nIt's not too late to chicken out, {name}. I'd certainly understand.\n\nBut if you're ready for some action, step in the Ring of Blood and wait for the Murkblood twins to arrive.\n\nLast one standing is the winner!", progress = "The fight's over when you or your opponent are dead on the floor.", completion = "I'll admit that I didn't think you had a prayer, {name}! That was amazing! So how 'bout another fight? Gurgthock's got the perfect match lined up.", objectives = "Defeat the Murkblood Twins that call themselves the Blue Brothers. Should you win, speak with Wodin the Troll-Servant to collect your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9968] = { id = 9968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange Energy", description = "Something strange has changed the teromoths of the thicket.\n\nWhere once there was a diversity of life in there, now only the teromoths remain.  And while before they were at peace, now they are agitated and will not hesitate to attack you should you get close.\n\nI need to compare the vicious ones to the normal.  Collect for me a number of samples from both.  You'll find the unaffected teromoths both to the south and the north.\n\nI'm certain this is related to whatever killed all of the druids.", progress = "Do you have my samples?", completion = "Odd.  The samples from the vicious teromoths are infused with what feels to me to be pure mana.\n\nIt would seem that whatever caused all of this death also left behind that strong field of residual energy.  But for some reason the teromoths were not killed by it; instead being driven into an agitated state.\n\nIt seems apparent that this strange energy is the by-product of whatever attacked the thicket.", objectives = "Collect 4 Teromoth Samples and 4 Vicious Teromoth Samples. Then return to Earthbinder Tavgren just outside of the Cenarion Thicket in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9969] = { id = 9969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Reagents", description = "I can create an item that will neutralize the ward spells protecting Veil Shalas, but be warned, {name}. The magic will only work as long as your friend is held captive. I will not give you a means to attack my people at will.\n\nI have most of the materials I require to create the charm, but there are a couple that I'm going to need you to gather before I can finish the work. I'll need some warp hunter essence and a handful of Terokkar chokeberries. Both can be found in the area around the veil.", objectives = "Bring 5 Warp Hunter Essences and 30 Terokkar Chokeberries to Kokorek in Veil Lithic.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9970] = { id = 9970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ring of Blood: Rokdar the Sundered Lord", description = "This fight is gonna be painful, {name}. Do you have any friends that are brave enough to help you out? The ogres managed to get a giant from Blade's Edge named Rokdar! Trust me, you're gonna need friends, he seems unbeatable! He's hard as a rock - literally!\n\nIf you still want to fight him, step into the Ring of Blood and he will come.", progress = "The fight's over when you or your opponent are dead on the floor.", completion = "You've got the ogres sweatin', kid! Here's a little something extra this time - don't use 'em all in one place.\n\nAre you ready for another fight? Gurgthock's bettin' the bank on you!", objectives = "Defeat Rokdar the Sundered Lord. Should you win, speak with Wodin the Troll-Servant to collect your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9971] = { id = 9971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clues in the Thicket", description = "I have no idea what killed all of the druids here.  I've been away for a couple of days on a survey of the Bone Wastes to the south.\n\nPlease, you must help me to uncover what's behind this horrible tragedy.  Go into the thicket and look for a clue that might reveal something to us.  When I was in there briefly, I could have sworn I saw a dead Broken and a strange object next to him.\n\n And don't worry about Treelos - he might have been driven insane by what happened, but I think he's mostly harmless.", completion = "So, I was right.  That was the corpse of one of the Broken?  And you can confirm that there was a strange object on the ground next to him?\n\nThis doesn't make any sense.  What would one of the Broken be doing here?  And what is that thing it had with him?\n\nIs it what caused all of this death?", objectives = "Investigate the Strange Object next to the Broken Corpse to determine what might have befallen the Cenarion Thicket. Then return to Earthbinder Tavgren just outside the thicket in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9972] = { id = 9972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ring of Blood: Skra'gath", description = "You're murderin' 'em out there, kid! They got a ringer for the next match. They say he's a void lord or something... No way do they want you up against their champion. Did you here that palooka, Mogor, yapping at you? The bets are through the roof!\n\nGet in that ring and take this one out fast!", progress = "The fight's over when you or your opponent are dead on the floor.", completion = "KID! KID THIS IS IT! The next fight is the big one! The championship!\n\nOk, keep it cool. We don't want the ogres to know that we got anything going on. I get a cut of all this, after all.", objectives = "Defeat Skra'gath. Should you win, speak with Wodin the Troll-Servant to collect your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9973] = { id = 9973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ring of Blood: The Warmaul Champion", description = "They had to ship the champion in from the Blade's Edge gladiator pits. He was training on mountain giants - three at a time.\n\nIf you win this one, you become the new champion. What do you think your odds are, kid? Do you have a shot? Just give me the word and I'll bet the house on you.\n\nNow get in there and win!", completion = "Oh boy. Mogor has invoked his right of battle as hero of the Warmaul. You have to fight him!\n\nNobody ever said the Warmaul were good sports... erm... ogres.", objectives = "Defeat the Warmaul Champion. Should you win, speak with Wodin the Troll-Servant to collect your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9974] = { id = 9974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Reagents", description = "I can create an item that will neutralize the ward spells protecting Veil Shalas, but be warned, {name}. The magic will only work as long as your friend is held captive. I will not give you a means to attack my people at will.\n\nI have most of the materials I require to create the charm, but there are a couple that I'm going to need you to gather before I can finish the work. I'll need some warp hunter essence and a handful of Terokkar chokeberries. Both can be found in the area around the veil.", objectives = "Bring 5 Warp Hunter Essences and 30 Terokkar Chokeberries to Kokorek at Veil Lithic.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9975] = { id = 9975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primal Magic", description = "I've stored the spell inside this talisman. Unleash it while standing near the totems that guard the approach to Veil Shalas. It should be sufficient to unravel the wards.\n\n<You mention that the figure in the talisman doesn't especially resemble an arakkoa.>\n\nMy people weren't always as they appear now. We were once magnificent creatures, but we... we made many ill-advised choices and failed in our sacred task. It cost us our beauty, our power, and very nearly our lives. Do not repeat our mistakes, {name}.", objectives = "Use Kokorek's Talisman near the totems that guard the path to Veil Shalas, then speak with Prospector Balmoral.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9976] = { id = 9976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primal Magic", description = "I've stored the spell inside this talisman. Unleash it while standing near the totems that guard the approach to Veil Shalas. It should be sufficient to unravel the wards.\n\n<You mention that the figure in the talisman doesn't especially resemble an arakkoa.>\n\nMy people weren't always as they appear now. We were once magnificent creatures, but we... we made many ill-advised choices and failed in our sacred task. It cost us our beauty, our power, and very nearly our lives. Do not repeat our mistakes, {name}.", objectives = "Use Kokorek's Talisman near the totems that guard the path to Veil Shalas, then speak with Lookout Nodak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9977] = { id = 9977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ring of Blood: The Final Challenge", description = "<Gurgthock is counting his massive pile of gold.>\n\nYou've made me a lot of money, kid. If you can defeat Mogor, I promise to make it worth your while. All that pain you suffered in the Ring of Blood is gonna end up paying off.\n\nNow get in there and show these ogres what you're made of!", progress = "The fight's over when you or your opponent are dead on the floor.", completion = "Gurgthock told you he'd make it worth your while, kid. Take your pick!", objectives = "Defeat Mogor, Hero of the Warmaul. Should you win, speak with Wodin the Troll-Servant to collect your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9978] = { id = 9978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By Any Means Necessary", description = "I don't know what to make of all of this, but I do know how we can find more clues.\n\nEmpoor is a Broken merchant that traffics in all sorts of goods and information.  If you were to persuade him to talk, I'm sure he might have something interesting to say.\n\nHe travels the road here between Tuurem and Shattrath.  Watch out, though -- he travels with a bodyguard.", completion = "Fine, fine... I'll tell you what I know, but it's not much!", objectives = "Find Empoor on the road between Tuurem and Shattrath City in Terokkar Forest. Convince him to tell you what he knows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9979] = { id = 9979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wind Trader Lathrai", description = "I was asked to pick up and deliver some boxes of goods from an ethereal in Shattrath City.\n\nLast I saw him, he was standing outside of the World's End Tavern in Lower City.  His name is Wind Trader Lathrai, and that's all that I know!\n\nWant more answers, go talk with him!", completion = "Yes?  How may I help you today, {race}?", objectives = "Speak with Wind Trader Lathrai near the World's End Tavern in the Lower City section of Shattrath City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9980] = { id = 9980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue Deirom!", description = "Make your way to Veil Shalas with all haste, {name}! Time is of the essence here. If the arakkoa discover what you've done to their defenses, they may attempt to move Deirom, or even kill him.\n\nIf you can, bring a friend or two with you. It's likely to be rough there. The bird-men have gone to great lengths to secure their prisoner and they're not likely to give him up easily. After you've found Deirom and dealt with his captor, return to the Allerian Stronghold and notify Thander.", objectives = "Venture into Veil Shalas, kill Luanga, and free Deirom. Report to Lady Dena Kennedy at the Allerian Stronghold when you have completed your mission.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9981] = { id = 9981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue Dugar!", description = "Make your way to Veil Shalas with all haste, {name}! Time is of the essence here. If the arakkoa discover what you've done to their defenses, they may attempt to move Dugar, or even kill him.\n\nIf you can, bring a friend or two with you. It's likely to be rough there. The bird-men have gone to great lengths to secure their prisoner and they're not likely to give him up easily. After you've found Dugar and dealt with his captor, return to Stonebreaker Hold and notify Rokag.", objectives = "Venture into Veil Shalas, kill Luanga, and free Dugar. Report to Rokag at Stonebreaker Hold when you have completed your mission.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9982] = { id = 9982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He Called Himself Altruis...", description = "A being riding atop a nether drake arrived in town late last week. He introduced himself as Altruis and then proceeded to ask us several questions about Nagrand.\n\nHe claimed that he was hunting Legion. That such insanity was actually his job. Can you imagine? A person that would willingly hunt demons?\n\nBefore he left, he asked that we let the would-be heroes in town know that he will be staying in western Nagrand for awhile and that should they seek a purpose, to find him.", completion = "Does my appearance startle you? Do you know what I am?", objectives = "If you are looking to fight the Burning Legion, find Altruis the Sufferer in western Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9983] = { id = 9983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He Called Himself Altruis...", description = "A being riding atop a nether drake arrived in town late last week. He introduced himself as Altruis and then proceeded to ask us several questions about Nagrand.\n\nHe claimed that he was hunting Legion. That such insanity was actually his job. Can you imagine? A person that would willingly hunt demons?\n\nBefore he left, he asked that we let the would-be heroes in town know that he will be staying in western Nagrand for awhile and that should they seek a purpose, to find him.", completion = "Does my appearance startle you? Do you know what I am?", objectives = "If you are looking to fight the Burning Legion, find Altruis the Sufferer in western Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9984] = { id = 9984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Host of the Hidden City", description = "Although you cannot read the strange script on the scroll, the ornate seal at the bottom of the document implies that it was drafted by an arakkoa of high standing. Luanga may have masterminded the capture and interrogation of Deirom, but it seems he was taking orders from someone else.\n\nYou remember Thander mentioning that Andarl has studied the arakkoa. Perhaps he can decipher the scroll's contents.", objectives = "Take Luanga's Orders to Andarl at the Allerian Stronghold in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9985] = { id = 9985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Host of the Hidden City", description = "Although you cannot read the strange script on the scroll, the ornate seal at the bottom of the document implies that it was drafted by an arakkoa of high standing. Luanga may have masterminded the capture and interrogation of Dugar, but it seems he was taking orders from someone else.\n\nYou remember Rokag mentioning that Kurgatok has studied the arakkoa. Perhaps he can decipher the scroll's contents.", objectives = "Bring Luanga's Orders to Kurgatok at Stonebreaker Hold in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9986] = { id = 9986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stymying the Arakkoa", description = "We need to show the arakkoa that they cannot attack our people with impunity. If we don't stop them here, the roads will no longer be safe for our merchants, couriers, or soldiers.\n\nMy scouts have identified the leaders of each of the major arakkoa settlements in the area. Seek out Ashkaz, Ayit, and Urdak, in Veil Reskk, Veil Shienor, and Veil Skith and kill them.", completion = "Well done, {name}. We have enough to worry about without wondering when the arakkoa will accost our merchants and messengers again.", objectives = "Kill Ashkaz in Veil Reskk, Ayit in Veil Shienor, and Urdak in Veil Skith and return to Thander at the Allerian Stronghold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9987] = { id = 9987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stymying the Arakkoa", description = "We need to show the arakkoa that they cannot attack our people with impunity. If we don't stop them here, the roads will no longer be safe for our merchants, couriers, or soldiers.\n\nMy scouts have identified the leaders of each of the major arakkoa settlements in the area. Seek out Ashkaz, Ayit, and Urdak, in Veil Reskk, Veil Shienor, and Veil Skith and kill them.", completion = "Well done, {name}. We have enough to worry about without wondering when the arakkoa will accost our merchants and messengers again.", objectives = "Kill Ashkaz in Veil Reskk, Ayit in Veil Shienor, and Urdak in Veil Skith and return to Rokag at Stonebreaker Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9988] = { id = 9988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dandy's Best Friend", description = "Don't let Thander and company fool you. They may look like a band of fearsome warriors, but underneath all that steel, they're nothing more than a troop of dandies!\n\nAnd they won't be seen in public without their hats. They're extravagant affairs made from felt and fur, complete with the gaudiest feathers you've ever seen.\n\nThe most desirable feathers come from any of the arakkoa, of course, and my supply is running low. I'll gladly pay you if you'll collect them for me.", objectives = "Bring 30 Arakkoa Feathers to Ros'eleth in the Allerian Stronghold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9989] = { id = 9989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alien Spirits", description = "When I first came to Outland, and opened my ears to the voices of its spirits, I was amazed at what I heard. In time, I also came to notice which spirits I couldn't hear.\n\nFor all my attempts, I have never been able to make contact with the spirit of an arakkoa ancestor. Their magic is fundamentally different from ours, but I'm not convinced that their spirits are beyond my reach.\n\nBring me feathers from many arakkoa; perhaps having some token from them will provide the link I need.", objectives = "Bring 30 Arakkoa Feathers to Malukaz at Stonebreaker Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9990] = { id = 9990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate Tuurem", description = "You know, come to think of it, I do recall selling several boxes of strange and exotic engineering parts to Empoor about a month ago.  I'm not sure what they'd be used for, but I know that they were delivered to Tuurem.\n\nPerhaps one or more of those boxes is still there?", progress = "What news do you bring, {name}?", completion = "Ethereals?  Goods delivered to Tuurem?  Exotic engineering parts?  And a blood elf getting ready to deliver this last box to Firewing Point?\n\nWhat does all of this mean?!  How does it relate to what happened to the druids in the Cenarion Thicket?\n\nI think we should have a look inside that box.", objectives = "Find the Sealed Box and then deliver it to Earthbinder Tavgren just outside of the Cenarion Thicket in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9991] = { id = 9991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survey the Land", description = "To be my eyes will require some diligence on your part. Nethrandamus will take you through the Legion camps, but you must catalog everything that you see. Even the smallest detail that you may think to be inconsequential could be useful for our purposes.\n\nPrimarily, I want you to note what structures are in the camps and what comprises the camps' defenses.\n\nNethrandamus is ready when you are, {name}. Do not be afraid, he will keep you safe from harm.", progress = "Never flown on the back of a nether drake, eh?", completion = "Excellent work, {name}! We now have a point from which we can plan our counter-attack.", objectives = "Sit back and enjoy the ride. Speak to Altruis when the survey is complete.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9992] = { id = 9992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Olemba Seeds", description = "Aren't the trees in the forest beautiful? I've often wondered if they would survive on Azeroth.\n\nI'm hesitant to send back seedlings, though. It's a rough trip and they're much harder to transport than something like a sack of seeds. The seeds are stored in tough cones that fall from the tree's branches once they've reached maturity.\n\nIf you come upon some of those cones in your travels, would you mind bringing some of the seeds back to me?", progress = "I've started a seed collection, but I'm going to need some help before I have enough to send back to the park in Stormwind.", completion = "Thank you for bringing these seeds. I've almost got enough to send back the first batch!", objectives = "Gather 30 Olemba Seeds and return them to Ros'eleth in the Allerian Stronghold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9993] = { id = 9993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Olemba Seed Oil", description = "The oily seeds from the forest's olemba trees could prove very valuable. I'd like to gather a larger quantity of them, press them for their oil, and then see what I can do with it.\n\nJust think, there's a whole forest full of trees out there, producing a lot of seeds that go to waste. I don't care if it turns out to be cooking oil, lamp oil, or weapon oil, I won't let it go to waste!\n\nBring me any of the seeds that you happen to gather from the olemba cones. They're all over the place.", progress = "Do you have any seeds for me?", completion = "That's a good start, but we're going to need more than that if we're to press a respectable amount of oil!", objectives = "Bring 30 Olemba Seeds to Rakoria in Stonebreaker Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9994] = { id = 9994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Are These Things?", description = "I don't know about you, but I have no idea what all of those things are.  I do know one thing though - they look dangerous!\n\n{name}, I think you should take this box of parts to Jenai Starwhisper at the Allerian Stronghold to the southeast.  She may have some idea of what these are.", progress = "You look concerned.  What is it, {class}?", completion = "Oh no!  That's horrible news!  I can't believe that all but two of our Cenarion friends are dead.\n\nAlright, let me have a look at those parts.  I'm just hoping they aren't what I suspect that they might be.\n\nYes, as I feared, I believe these are bomb parts.  Our eyes and ears in Shattrath City have been feeding us information about some of the ethereals importing proscribed goods from other dimensions that they're in contact with.", objectives = "Deliver the Box of Parts to Jenai Starwhisper at the Allerian Stronghold in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9995] = { id = 9995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Are These Things?", description = "I don't know about you, but I have no idea what all of those things are.  I do know one thing though - they look dangerous!\n\n{name}, I think you should take this box of parts to Tooki at Stonebreaker Hold to the southeast.  He may have some idea of what these are.", progress = "You look concerned.  What is it, {class}?", completion = "Oh no!  That's horrible news!  I can't believe that all but two of our Cenarion friends are dead.\n\nAlright, let me have a look at those parts.  I'm just hoping they aren't what I suspect that they might be.", objectives = "Deliver the Box of Parts to Tooki at Stonebreaker Hold in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9996] = { id = 9996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack on Firewing Point", description = "We know that the blood elves of Firewing Point are working for Kael'thas and Illidan.  And from what you've told me, clearly they are using the Broken of Tuurem as smuggling go-betweens for the creation of some horrible weapon.\n\nWhatever they're up to out there, the most efficient thing that we can do right now is to thin out their numbers.\n\nThe Firewing blood elves need to be taken out!  Head up to Firewing Point to the north and see to it.", completion = "That's a good start, but based on what you witnessed there in the courtyard, as well as intelligence that I've received, we have a far more pressing matter at hand!", objectives = "Kill 10 Firewing Defenders, 10 Firewing Bloodwarders, and 10 Firewing Warlocks. Then report back to Lieutenant Meridian at the Allerian Post in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9997] = { id = 9997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack on Firewing Point", description = "We know that the blood elves of Firewing Point are working for Kael'thas and Illidan.  And from what you've told me, clearly they are using the Broken of Tuurem as smuggling go-betweens for the creation of some horrible weapon.\n\nWhatever they're up to out there, the most efficient thing that we can do right now is to thin out their numbers.\n\nThe Firewing blood elves need to be taken out!  Head over to Firewing Point to the northeast and see to it.", completion = "That's a good start, but based on what you witnessed there in the courtyard, as well as intelligence that I've received, we have a far more pressing matter at hand!", objectives = "Kill 10 Firewing Defenders, 10 Firewing Bloodwarders, and 10 Firewing Warlocks. Then report back to Sergeant Chawni at Stonebreaker Camp in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9998] = { id = 9998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unruly Neighbors", description = "The recent arrival of the fel orcs at the ruins to the east both puzzles and troubles Thander. They wasted no time in starting to construct fortifications and repair the buildings.\n\nThe construction goes on day and night, {name}. I've dispatched one of my most reliable agents to keep watch, but we can ill afford to delay action. Move against their workers, then seek out Theloria Shadecloak at the Allerian Post to the north of the Bonechewer Ruins. She'll give you further instructions.", progress = "I take it Bertelm sent you to hamper the efforts of their peons?", completion = "<The high elf nods.>\n\nIt's a good start, but Bertelm was right to send you to me. I've made a discovery that may help explain the fel orc presence here.", objectives = "Kill 12 Warped Peons and then report to Theloria Shadecloak at the Allerian Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9999] = { id = 9999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buying Time", description = "As long as the transporters stand, nothing we do to the forge camps will have any permanence. We must find a way to destroy the Legion structures.\n\nI need time to devise a plan of attack. If you can keep their engineers and tinkerers busy, it would greatly slow down their progress, buying me the time I need.", progress = "Back so soon?", completion = "It is as I suspected. There are no conventional means of destroying fel steel. All is not lost, however...", objectives = "Altruis the Sufferer in western Nagrand has asked that you kill 2 Felguard Legionnaires, 3 Mo'arg Engineers and 8 Gan'arg Tinkerers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10000] = { id = 10000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unwelcome Presence", description = "Our forces at Thrallmar thought they had the fel orcs contained in the Hellfire Citadel area, but the recent arrivals at the ruins to the east say otherwise.\n\nWe can't permit them to gain a foothold here. Rokag has dispatched Shadowstalker Kaide to the ruins to keep an eye on them, but we have to do something to keep them from digging in.\n\nGo to the ruins, decimate their peons, and then look for Kaide in the trees to the north. He'll tell you where to go from there.", completion = "Stopping the fel orcs is going to take more than merely harassing their workers, I'm afraid. I've made a discovery that's shed some light on the reason for their presence here and it's reinforced my belief that we must act quickly.", objectives = "Kill 12 Warped Peons and then report to Shadowstalker Kaide.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10001] = { id = 10001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master Planner", description = "All forge camps have a master planner. The master planner dictates what types of structures are present at a forge camp and how each structure is situated. Moreover, this information is kept on a set of blueprints that the planner carries around on their person.\n\nWe need the master planner's blueprints. Armed with such exacting information, we could persuade an acquaintance of mine to lend some assistance.\n\nFind the mo'arg master planner and take his blueprints. He will be stationed behind the forges.", progress = "Avoid the overseers at all costs. They must not be let on to your presence. The results could be disastrous!", completion = "My acquaintance will hopefully know of a way to destroy the camps. He was a Legion engineer, after all...", objectives = "Altruis the Sufferer in western Nagrand has asked that you recover the Master Planner's Blueprints.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10002] = { id = 10002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Firewing Liaison", description = "Over the past couple of days, I've observed a blood elf woman traveling to and from the fel orc stronghold and conversing with the fel orc leader. From her body language, she's clearly issuing orders. But why? Whose orders is she conveying?\n\nMy curiosity got the better of my judgment and I shadowed her when she left the fel orc encampment. She headed north, to Firewing Point. I stopped before reaching the perimeter of the blood elf outpost.\n\nKill her before she leaves the fel orc camp again.", completion = "<Theloria nods at you.>\n\nWell done. We have bought ourselves a little time. The blood elves will grow curious about what happened to their friend. Hopefully, by that time, we will have a better understanding of their intentions.", objectives = "Locate and slay Lisaile Fireweaver, then return to Theloria Shadecloak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10003] = { id = 10003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Firewing Liaison", description = "Over the past couple of days, I've observed a blood elf woman traveling to and from the fel orc stronghold and conversing with the fel orc leader. From her body language, she's clearly issuing orders. But why? Whose orders is she conveying?\n\nMy curiosity got the better of my judgment and I shadowed her when she left the fel orc encampment. She headed north, to Firewing Point. I stopped before reaching the perimeter of the blood elf outpost.\n\nKill her before she leaves the fel orc camp again.", completion = "<Kaide nods at you.>\n\nWell done. We have bought ourselves a little time. The blood elves will grow curious about what happened to their friend. Hopefully, by that time, we will have a better understanding of their intentions.\n\nWhen the time is right, I will inform Rogak of our progress.", objectives = "Locate and slay Lisaile Fireweaver, then return to Shadowstalker Kaide.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10004] = { id = 10004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patience and Understanding", description = "Take the blueprints and travel to Shattrath City in the Terokkar Forest. Once at Shattrath, go to the Lower City and look for a mo'arg by the name Sal'salabim. He'll probably be at the bar, drinking away his sorrows.\n\nBy the way, you may need to convince him to lend his assistance. Try to approach him with patience and understanding. If that does not work, use your fists.", progress = "<Sal'salabim rubs his head.>\n\n[Demonic] Ik il romath sardon.", completion = "Calm down, bright eyes! Sal'salabim will help.", objectives = "Altruis the Sufferer in western Nagrand wants you to take the Master Planner's Blueprints to Sal'salabim in Shattrath City and convince him to help you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10005] = { id = 10005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letting Earthbinder Tavgren Know", description = "{name}, after you're done celebrating here, I think that you should go back to the Cenarion Thicket and speak with Earthbinder Tavgren.\n\nI'm certain that he'll want to know what really happened out there.", completion = "A bomb utilizing pure mana that can take out whole towns!  But why?  Why would the blood elves create such a thing and use it on us?  The Cenarion Thicket was a place of peace and repose.\n\nWhatever the reason, it must be locked inside the head of Warden Treelos, and I have no idea how to cure him.  Perhaps his mind will heal in time?\n\nRegardless, I want to thank you for helping me to figure out what happened.  I can only hope that this tragedy will never befall anyone else ever again!", objectives = "Speak with Earthbinder Tavgren just outside the Cenarion Thicket in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10006] = { id = 10006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letting Earthbinder Tavgren Know", description = "{name}, I think that after you're done celebrating here, you should go back to the Cenarion Thicket and speak with Earthbinder Tavgren.\n\nI'm certain that he'll want to know what really happened out there.", completion = "A bomb utilizing pure mana that can take out whole towns!  But why?  Why would the blood elves create such a thing and use it on us?  The Cenarion Thicket was a place of peace and repose.\n\nWhatever the reason, it must be locked inside the head of Warden Treelos, and I have no idea how to cure him.  Perhaps his mind will heal in time?\n\nRegardless, I want to thank you for helping me to figure out what happened.  I can only hope that this tragedy will never befall anyone else ever again!", objectives = "Speak with Earthbinder Tavgren just outside the Cenarion Thicket in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10007] = { id = 10007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thinning the Ranks", description = "Knowing Thander and Bertelm, they won't tolerate such a large buildup of hostile forces on our doorstep. Asking them to dispatch members of the garrison to participate in an attack on the camp isn't an option either. It would just leave us too vulnerable to attack.\n\nIt falls to us to do what we can to diminish the threat the fel orc buildup poses. Kill what you can of their forces and I will look for ways to stall any reinforcements.", completion = "Things are starting to look up. I think if we can prevent the fel orcs from reinforcing their fellows here, we can keep this post under control.", objectives = "Kill 10 Bonechewer Devastators and 6 Bonechewer Backbreakers and return to Theloria Shadecloak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10008] = { id = 10008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Happens in Terokkar Stays in Terokkar", description = "If word reaches Thrallmar that they've failed to contain the fel orcs, we're going to be receiving a lot of company down here. Frankly, I'm not sure I want all that attention, so we're going to keep this little problem under wraps, got it?\n\nIf we can inflict enough casualties on the fel orcs, chances are their presence will never come to the attention of anyone outside Stonebreaker. So, let's end it now.\n\nWade in there, swing your weapon, wave your hands, or whatever it is you do - just kill fel orcs.", completion = "I know you're well-traveled, but understand, {name}, that some stories are best left where they happened. Do we understand each other?", objectives = "Shadowstalker Kaide wants you to kill 10 Bonechewer Devastators and 6 Bonechewer Backbreakers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10009] = { id = 10009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crackin' Some Skulls", description = "<Sal'salabim laughs.>\n\nThis Sal'salabim design.\n\n<Sal'salabim points to the architecture and formations on the blueprints.>\n\nLook at towers. Demon hunter no can see, yes? Poor, poor Altruis. He cry if he had eyes, yes?\n\nYes, Sal'salabim help but first you help Sal'salabim.\n\n<Sal'salabim gives you a ledger.>\n\nThese creatures owe Sal'salabim golds. Many golds. Go collect for Sal'salabim and come back. They no give you Sal'salabim gold easy. Have to fight, but you strong. You defeat Sal'salabim!", progress = "You no come back without Sal'salabim golds!", completion = "Now, deal is deal but when Sal'salabim tell you, you not be mad, yes?", objectives = "Sal'salabim at Shattrath City wants you to recover Raliq's Debt, Coosh'coosh's Debt and Floon's Debt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10010] = { id = 10010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Just That Easy?", description = "<Sal'salabim points to the blueprint.>\n\nYou see where fel cannons are?\n\n<Sal'salabim draws an arrow denoting a change of direction.>\n\nYou turn fel cannon around and use on structures.\n\nWait! Don't be mad! One thing you not know. Overseers have key to turn cannons. You need key first! One from each overseer!\n\nNot so easy, eh?\n\nTake information back to Altruis.", completion = "Of course! We will use their own weapons against them!", objectives = "Sal'salabim at Shattrath City wants you to return to Altruis the Sufferer in western Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10011] = { id = 10011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forge Camp: Annihilated", description = "Gather your courage, {name}. You will need it if you are to face an overseer.\n\nOnce you are ready, find and kill the overseers at each camp. Take their keys and use them to turn and fire the fel cannons upon the camps. Return to me once the camps are destroyed.", progress = "Is it done?", completion = "We are victorious! The Legion's advances have been halted!\n\nI offer you a choice of rewards for your heroic deeds!", objectives = "Altruis the Sufferer in western Nagrand has asked that you Destroy Forge Camp: Hate and Destroy Forge Camp: Fear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10012] = { id = 10012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Orc Plans", description = "The writing on the plans is far too delicate and precise to have come from any of the fel orcs. You can't make out what the text says, but the implications are pretty clear: the fel orcs are taking orders from the blood elves at Firewing Point.\n\nWhy would the two forces be working together? Bertelm might have some insight into this odd alliance. You decide to make your way back to the Allerian Stronghold and show him the map.", progress = "What is it you have there, {name}?", completion = "<Bertelm takes the plans from you and looks them over.>\n\nIf you hadn't brought this map, I'd say you were out of your mind, but here it is, plain as day. Not only are the fel orcs here to serve the blood elves, but it appears, they've been ordered to keep us occupied.\n\nThis map raises more questions than it answers, but it gives us a better idea of what we're facing here.", objectives = "Bring the Fel Orc Plans to Bertelm at the Allerian Stronghold in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10013] = { id = 10013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unseen Hand", description = "The writing on the plans is far too delicate and precise to have come from any of the fel orcs. You can't make out what the text says, but the implications are pretty clear: the fel orcs are taking orders from the blood elves at Firewing Point.\n\nWhy would the two forces be working together? Rokag might have some insight into this odd alliance. You decide to make your way back to Stonebreaker Hold and show him the map.", progress = "What is it you have there, {name}?", completion = "<Rokag takes the plans from you and looks them over.>\n\nSo Kaide was right! Those fel orc scum are up to something. I never would've guessed they were colluding with the blood elves, though.\n\nAccording to this map, the fel orcs are to keep us busy... but why? This is disturbing news, {name}. You were correct in bringing it to me right away.", objectives = "Bring the Fel Orc Plans to Rokag at Stonebreaker Hold in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10014] = { id = 10014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Firewing Point Project", description = "As I was saying, we've just received some further intel and there's a much larger problem at hand.\n\nThe blood elves are hard at work on the construction of a second bomb at Firewing Point.  I cannot stress strongly enough the implications of them completing and using such a device on the Allerian Stronghold!\n\nMy scouts tell me that they are guarding the codes to the device in the four smaller buildings ringing the central courtyard.  Get in there and retrieve those codes before it's too late!", objectives = "Steal the four Mana Bomb Code Sheets and deliver them to Lieutenant Meridian at the Allerian Post in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10015] = { id = 10015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Firewing Point Project", description = "As I was saying, we've just received some further intel and there's a much larger problem at hand.\n\nThe blood elves are hard at work on the construction of a second bomb at Firewing Point.  I cannot stress strongly enough the implications of them completing and using such a device on Stonebreaker Hold!\n\nMy scouts tell me that they are guarding the codes to the device in the four smaller buildings ringing the central courtyard.  Get in there and retrieve those codes before it's too late!", objectives = "Steal the four Mana Bomb Code Sheets and deliver them to Sergeant Chawni at Stonebreaker Camp in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10016] = { id = 10016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timber Worg Tails", description = "Have you come across the timber worgs in your travels? I've had the opportunity to observe them while mapping some of the northern reaches of the forest. I wouldn't recommend getting close to them unless you're prepared for combat.\n\nThey have no fear of us and won't hesitate to defend their territory.\n\nIt's fitting that such a creature would have a magnificent tail. I've been trying to collect enough of them to trim a new cloak, but the worgs have a habit of evading my snares. Will you help?", progress = "I see you've managed to survive the rigors of the forest. Have you brought any tails for my cloak?", completion = "Ah, well done, friend. These are finer than I thought they'd be. They'll make a fine cloak.\n\n<Bertelm glances toward the inn.>\n\nYes, a fine cloak it shall be.", objectives = "Bertelm at the Allerian Stronghold wants you to bring him 12 Timber Worg Tails. The tails can come from either Timber Worgs or Timber Worg Alphas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10017] = { id = 10017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strained Supplies", description = "More and more refugees come through the gates of Shattrath City each day.  Some have sustained such injuries, it's a real wonder they made it here.\n\nI can deal with most of the conventional injuries; my training as an Aldor healer has prepared me for that.  Poison wounds are more problematic as my anti-venom supplies have begun to run low.\n\nBring me venom sacs from the local dreadfang spiders so I can produce more antidotes.  You'll find a pocket of the spiders in the southeastern region of Terokkar.", progress = "Have you obtained the venom sacs, {name}?  These refugees can't wait much longer.", completion = "You have my thanks, {name}.  The Aldor will hear of your actions.", objectives = "Bring 8 Dreadfang Venom Sacs to Sha'nir in Shattrath City.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10018] = { id = 10018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vestments of the Wolf Spirit", description = "Generations ago, when orc clans still called Terokkar Forest home, the wolf spirit played an important role in their lives. When the orcs departed, they had no longer had any need for the spirit and they left it behind.\n\nIn time, the spirit grew lonely and it too left the forest.\n\nI believe I can bring the wolf spirit back to his ancestral home, just as we orcs have returned. The ritual will require me to create vestments from the pelts of the wolves of the forest to guide the spirit back to its home.", progress = "Were you able to find all the pelts that I need?", completion = "These are perfect, {name}! I could not have asked for better.", objectives = "Bring 12 Timber Worg Pelts to Malukaz at Stonebreaker Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10019] = { id = 10019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Venom Sacs", progress = "Many refugees still need treatment for their poisonous wounds.  Have you brought more venom sacs for me to use, {name}?", completion = "You have my thanks, {name}.  The naaru have extended their protection to these unfortunate souls; it would be a shame if they made it to Shattrath and perished to previous wounds." }
quests[10020] = { id = 10020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cure for Zahlia", description = "The woman to my right suffered a severe injury to the head.  She survived, but lost her eyesight.\n\nA traditional cure used among my people requires the blood of a very old basilisk.\n\nUnfortunately, due to poaching from various groups, Terokkar basilisks don't tend to live very long.\n\nThere is one basilisk whose name I've known since I was a youngling.  It is known only as \"Stonegazer\" and it's rumored to live east of here, near the land's edge.\n\nBring me its blood so that Zahlia may see once again.", progress = "Have you obtained the blood, {name}?  Without it, Zahlia may never see her son again.", completion = "Thank you, {name}.  Caring for those in need is a difficult task, but in time I've discovered that it is its own reward.", objectives = "Bring Stonegazer's Blood to Sha'nir in Shattrath City.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10021] = { id = 10021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoring the Light", description = "Much of this region was inhabited by draenei long ago.  We Aldor were charged with the safeguarding of our holy sites and altars.  Many of them have since been destroyed or taken over by our enemies.\n\nTo the east of here there is an arakkoa outpost.  It was purposefully built on the location of three of our sacred altars. The arakkoa use their foul magic to warp and defile the innate power of our shrines.\n\nTake this to the arakkoa outpost and use it to cleanse the three altars.", progress = "Have you completed your task, {name}?", completion = "You have my thanks, {name}.  We are keepers of the light and cannot forsake our responsibilities, even in the most difficult of times.", objectives = "Ishanah wants you to go to the Arakkoa outpost east of Shattrath City and use the Blessed Vial to cleanse the Eastern Altar, the Western Altar and the Northern Altar.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10022] = { id = 10022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Elusive Ironjaw", description = "Now that I have the fur I'll need for the trim, I've been thinking that the pelt of a particular wolf would make a good hood for my cloak. Imagine seeing your enemy clad in the pelt of the most cunning predator in the forest!\n\nI've tried trapping old Ironjaw without success. I've tried cornering him, outsmarting him, and baiting him. None of it has worked.\n\nHe stalks the northeastern reaches of the forest, and I'd gladly reward you if you could succeed where I have failed.", progress = "Has old Ironjaw gotten the better of you, too, friend? Or have you managed to outsmart the old fellow?", completion = "I bow to your skills, {name}. You have proven yourself the superior hunter.\n\nI won't forget your help in making this cloak. It will truly be a one-of-a-kind piece and I'll wear it proudly.", objectives = "Bring Ironjaw's Pelt to Bertelm at the Allerian Stronghold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10023] = { id = 10023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patriarch Ironjaw", description = "You've done well in gathering the first pelts.\n\nThe final piece of the vestments requires a pelt unlike any other. There is one particular wolf, an old and cunning one, that has earned his place as the patriarch of the forest wolves. He is known among them as Ironjaw, the mighty hunter.\n\nIn my visions, I have seen him wandering the northeastern region of the forest. Including his pelt in the vestments will surely light the wolf spirit's path.\n\nDo not mourn Ironjaw. He will be well honored.", progress = "The spirit awaits, {name}. Have you the pelt of the wolf patriarch?", completion = "The pelt is even more magnificent than I had hoped! This is a good omen, {name}, and the spirits will favor you for your contribution to this ceremony.\n\nI have fashioned a helmet for you from the remaining pelts, {name}. It identifies you as a mighty hunter and an ally of the great wolf spirit of Terokkar Forest.", objectives = "Bring Ironjaw's Pelt to Malukaz at Stonebreaker Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10024] = { id = 10024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voren'thal's Visions", description = "Our leader, Voren'thal the Seer, was once a close advisor to Kael'thas.  His prophetic visions warned him that Kael's path would lead to the destruction of our race.\n\nThe visions are usually vague and unfocused, but our alchemists have devised an elixir to help him focus his clairvoyance.  Unfortunately, this elixir calls for a rare ingredient: basilisk eyes.  My usual source, this pathetic ethereal, has failed me.\n\nSeek the dampscale basilisks in the rocky regions of Terokkar and bring me their eyes.", progress = "Have you obtained the basilisk eyes for Voren'thal's elixir?", completion = "These are all in excellent state, {name}.  Carry on and you will soon count the Scryers as your friends.", objectives = "Bring 8 Dampscale Basilisk Eyes to Arcanist Adyria in Shattrath City.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10025] = { id = 10025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Basilisk Eyes", progress = "It takes many basilisk eyes to make even a small dose of Voren'thal's elixir.  Bringing me more would certainly incur the Scryers' favor.", completion = "I thank you, {name}.  Voren'thal's visions might one day decide the fate of our race.  It would behoove us to do our best to ensure that those visions are as accurate as possible." }
quests[10026] = { id = 10026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magical Disturbances", description = "It's embarrassing to admit this, but something has happened to me here in Terokkar Forest that hasn't occurred since my apprentice days.\n\nOccasionally, my spells will fizzle when I know I've done everything correctly. I almost drove myself crazy the first time it happened.\n\nI think I've found the cause. The forest is full of creatures called warp stalkers, demonic creatures with an affinity for magic and a habit of disturbing magical flows. The best way to deal with them is simply to kill them.", completion = "<Andarl dabs at his forehead with the sleeve of his robe.>\n\nThank goodness. I was beginning to wonder if the things had displaced the rest of the forest's creatures.", objectives = "Andarl at the Allerian Stronghold wants you to kill 10 Warp Stalkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10027] = { id = 10027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magical Disturbances", description = "There's nothing more annoying than preparing to cast a spell, only to have it interrupted by some unseen force. After the fourth time, I knew it couldn't be coincidence and I sent Keb'ezil out to investigate.\n\nI guarantee you'll never encounter an imp that talks back more than Keb.\n\nAnyway, he managed to find the source of the problem, a pesky creature known as a warp stalker. They have a habit of disturbing the magical energy wherever they blink into existence. I've had enough of their interference.", completion = "Keb'ezil is relieved that you've taken care of that little problem, aren't you, Keb?\n\n<The imp ignores its master, presumably out of indignation.>\n\nYou'll have to forgive his bad manners. You know how demons can be...", objectives = "Kill 10 Warp Stalkers and return to Kurgatok at Stonebreaker Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10028] = { id = 10028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vessels of Power", description = "Amid the ruins of Tuurem are a number of vessels containing raw, magical energy. We are fortunate that the Broken who have overrun the city are ignorant to the resource in their midst, but we cannot assume they will remain so forever.\n\nWith those vessels and their power in hand, the scattered survivors of my people can resist the lure of demonic magic. Every quel'dorei we can save from our prince's folly is one more that can help us regain our lost glory. Bring me these vessels, {class}.", progress = "Were you able to find any intact vessels?", completion = "I hope these aren't the only intact vessels in the city. This is a good start, but I suspect we'll need many more than this.", objectives = "Bring 8 Draenei Vessels to Ros'eleth at the Allerian Stronghold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10029] = { id = 10029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spirits Are Calling", description = "The spirits of the dead in the Bone Wastes have been calling out to me and they are in pain!\n\n{class}, you must journey to the Bone Wastes to the south and find my assistant, Soolaveen with the Refugee Caravan.  He must be feeling it too, and will need your assistance to help put the spirits there to rest.\n\nIf you hurry, you may catch them.  I know that they were going to stop for a while in the northern portion of the Bone Wastes before continuing south to Auchindoun.", objectives = "Anchorite Lyteera wants you to locate her assistant, Soolaveen at the Refugee Caravan in the Bone Wastes of Terokkar Forest.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10030] = { id = 10030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recover the Bones", description = "The bones of the dead draenei litter the Bone Wastes from the explosion of Auchindoun.  Their spirits are restless, and cannot move on to the next life.\n\n{class}, you must help me to recover their bones and take them to their final resting place!  Only then will they be at peace; only then will they know comfort.\n\nGather up the restless bones with care and deliver them to Ramdor the Mad at Auchindoun in the center of the Bone Wastes.  Despite his name, he will know how to care for them.", progress = "What's this?  Who are you?", completion = "Great, just what I needed... more bones.\n\n<Ramdor sighs.>\n\nYes, yes, I will see to it that these remains of our honored ancestors are given a proper burial, have no fear.\n\nThere is something else that you can do if you're truly interested in aiding the dead.", objectives = "Collect 10 Restless Bones. Deliver them to Ramdor the Mad, just off the western side of the Ring of Observance in Auchindoun, which is in the middle of the Bone Wastes of Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10031] = { id = 10031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helping the Lost Find Their Way", description = "Many spirits of the draenei were corrupted by the explosion of Auchindoun.  Now they wander the wastes in torment.\n\n{name}, I beseech you to put them to rest.  Destroy the lost spirits and broken skeletons that haunt the Bone Wastes beyond Auchindoun's walls.\n\nWhat?  You think leaving them to wander in blind agony would be better?\n\nAfterward, return to Soolaveen at the Refugee Caravan and tell him of that which you have done.", completion = "You have done that which needed doing and there is nothing to forgive.  Though it saddens me to hear that they were corrupted into a horrible undeath, through your actions you have put them to rest.\n\nThank you for setting them free, {name}.  You must accept a humble token of my regard for you and your selflessness.", objectives = "Destroy 10 Lost Spirits and 10 Broken Skeletons, and then speak with Soolaveen at the Refugee Caravan in the Bone Wastes of Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10032] = { id = 10032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artifacts from Tuurem", description = "Have you ever noticed the behavior of the Lost Ones in Tuurem? They wander the ruins, searching for surviving scraps of anything made by the draenei.\n\nTheir Broken masters know better. They've left their former lives and identities behind and become something completely different.\n\nI believe we can use the Lost Ones' compulsion to our benefit and gather old draenei relics from them. Why risk life and limb battling the Broken, when we can profit from picking our targets wisely?", objectives = "Gather 6 Tuurem Artifacts from Tuurem Scavengers and Tuurem Hunters and bring them to Rakoria at Stonebreaker Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10033] = { id = 10033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Bonelashers Dead!", description = "A bounty is declared on the bonelashers of the Bone Wastes.  As known carriers of the plague, they are to be destroyed forthwith!\n\nWhile they can be found throughout the wastes, they are known to congregate at Carrion Hill in the north.\n\nReport to Taela Everstride afterward to collect your reward.", completion = "Yeah, I'm sure that you killed all of those bonelashers.  It's obvious since the captain asked for you to turn in proof on that wanted poster.\n\n<Taela gives you a sarcastic look.>\n\nI'll take your word for it.  I'm not certain who I angered to pull this duty, but thanks for your efforts on behalf of the Alliance.  Here's a little something for all of your trouble.", objectives = "Kill 20 Bonelashers and then report to Taela Everstride at the Allerian Stronghold in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10034] = { id = 10034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Bonelashers Dead!", description = "The bonelashers of the Bone Wastes bit Mawg and made him sick.  Now he wants all of them destroyed!\n\nWhile they can be found throughout the wastes, they are known to congregate at Carrion Hill in the north.\n\nReturn to Mawg Grimshot after you've done the deed and he'll give you a good reward.", completion = "You must have killed a lot of those bonelashers!  Good, I hate them!  Ever since I was bit by one of them, I keep having fainting spells.\n\nDo you realize how embarrassing that is?  Here, take this as thanks for exacting some revenge for me.", objectives = "Kill 20 Bonelashers and then report to Mawg Grimshot at Stonebreaker Hold in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10035] = { id = 10035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torgos!", description = "There's a creature in the Bone Wastes so fearsome that only the dauntless dare to stalk him.\n\nI speak of Torgos, king of the bonelashers, who circles over Veil Rhaze on the western edge of the wastes.\n\nToo bad that there's an arakkoan scarecrow there, known as Torgos's Bane, which keeps him at bay.  I'd bet if you laid his mate Trachela's carcass at the foot of that scarecrow he'd come down anyway.  She can be found at Carrion Hill in the northern wastes.\n\nBring me one of Torgos's tail feathers.", progress = "You have the feather?  Am I to reward you for your foolhardy bravery?", completion = "Color me impressed, {class}.  Torgos was one of the toughest creatures I know of this side of Nagrand.\n\nWell, I suppose that's good enough for something from the Allerian Stronghold treasury.  Take your pick.", objectives = "Call down Torgos with Trachela's Carcass. Acquire a Tail Feather of Torgos and return it to Taela Everstride at the Allerian Stronghold in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10036] = { id = 10036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torgos!", description = "I want Torgos, king of the bonelashers, dead!\n\nNot long ago, while I was out hunting at Veil Rhaze on the western edge of the wastes, he fell upon me.\n\n<Mawg taps his eyepatch.>\n\nHe took my eye, and now I would have his life!  Bring me one of his tail feathers as proof and I'll give you a worthy reward.\n\nYou'll need his mate Trachela's carcass though to call him down as he's deathly afraid of the old arakkoan scarecrow known as Torgos's Bane.\n\nFind her at Carrion Hill in the northern wastes.", progress = "Did you kill him?  Is Torgos dead?!\n\nYou have proof?", completion = "I thank you, {name}!  You have exacted my revenge, and as promised you will be rewarded!\n\nTake your pick of one of these and use it well!", objectives = "Call down Torgos with Trachela's Carcass. Acquire a Tail Feather of Torgos and return it to Mawg Grimshot at Stonebreaker Hold in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10037] = { id = 10037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rather Be Fishin'", description = "Speaking of lakes, there's a lake with real good fishin' up to the northeast. I used to go up there with my friends, but my mom won't let me go anymore.\n\nShe says it's too dangerous, but I haven't seen anything up there but a few little spiders. Like spiders can do anything to you...\n\nMy favorites were always the eels that live up there. If you're going to be up by the lake, would you think about bringing back some of the eels? They're feisty but once you subdue 'em, you can bring 'em back no problem.", progress = "<Seth tugs on your cloak.>\n\nDid you find the eels? Didja?", completion = "Thanks! I can't remember the last time I had eel!\n\nHow should I cook 'em?", objectives = "Bring 8 Pristine Shimmerscale Eels to Seth in Shattrath City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10038] = { id = 10038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Private Weeks", description = "A report's just come in from one of our scouts near Grangol'var Village.  He says that a shadowy band has moved into the ruins there.\n\n{name}, I want you to speak with Private Weeks and see how you can assist him to figure out what this unknown group is up to.  Just head west past Stonebreaker Hold.  His last report puts his position near the north entrance to the village.", completion = "It's about time someone came out here.  I sent that report to the Allerian Stronghold over a week ago!\n\nBureaucracy!", objectives = "Speak with Private Weeks near the north entrance to Grangol'var Village in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10039] = { id = 10039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Scout Neftis", description = "I am informed that one of our scouts near Grangol'var Village is currently observing a shadowy band that has recently moved in there.\n\n{name}, I want you to speak with Scout Neftis and see how you can assist her in figuring out what this unknown group is up to.\n\nJust head south out of here, and then due west, skirting the north of the Bone Wastes.  Her last report puts her position near the southern entrance to the village.", completion = "It's about time someone came out here.  I sent that report to Stonebreaker Hold over a week ago!\n\nBlood elves and their bureaucracy!", objectives = "Speak with Scout Neftis near the south entrance to Grangol'var Village in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10040] = { id = 10040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who Are They?", description = "I don't know who they are, but I know they're hostile!\n\nI'm going to give you a disguise, and I want you to go in there and speak with three of them that I've observed as being 'chatty'. Talk with the initiate, the laborer, and the advisor.\n\nJust watch out; there're a few hunters in there who'll be able to see through your disguise and they look tough! And whatever you do, don't leave the village -- the disguise is kind of flimsy. If you lose your disguise, come back to me and I'll give you another.", completion = "Good, you finally made it back!  Okay, what did you figure out?  Who are they?", objectives = "While in disguise, speak with the Shadowy Initiate, the Shadowy Laborer and the Shadowy Advisor. Then return to Private Weeks at Grangol'var Village in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10041] = { id = 10041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who Are They?", description = "I don't know who they are, but I know they're hostile!\n\nI'm going to give you a disguise, and I want you to go in there and speak with three of them that I've observed as being 'chatty'. Talk with the initiate, the laborer, and the advisor.\n\nJust watch out; there're a few hunters in there who'll be able to see through your disguise and they look tough! And whatever you do, don't leave the village -- the disguise is kind of flimsy. If you lose your disguise, come back to me and I'll give you another.", completion = "Good, you finally made it back!  Okay, what did you figure out?  Who are they?", objectives = "While in disguise, speak with the Shadowy Initiate, the Shadowy Laborer and the Shadowy Advisor. Then return to Scout Neftis at Grangol'var Village in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10042] = { id = 10042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill the Shadow Council!", description = "What!  Those guys are Shadow Council?!\n\n{name}, you have to go back in there and waste them!  I want you to take out their leader and as many of their executioners and summoners as you can.\n\nAfter you're done with that, report back to Lieutenant Gravelhammer at the Allerian Stronghold.\n\nGood luck, {class}!", completion = "That's dire news indeed!  Well, it would seem I made the right choice in sending you out there to help Weeks.  The last thing that we want is the Shadow Council establishing themselves right on our doorstep!\n\n{name}, in recognition of your efforts at Grangol'var Village, I hereby grant you the right to your pick of any of these fine rewards.", objectives = "Kill 10 Shadowy Executioners, 10 Shadowy Summoners and Shadowmaster Grieve, and then return to Lieutenant Gravelhammer at the Allerian Stronghold in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10043] = { id = 10043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill the Shadow Council!", description = "What!  Those guys are Shadow Council?!\n\n{name}, you have to go back in there and waste them!  I want you to take out their leader and as many of their executioners and summoners as you can.\n\nAfter you're done with that, report back to Advisor Faila at Stonebreaker Hold.\n\nGood luck, {class}!", completion = "That is unfortunate news!  But, of course, I made the right choice in sending you out there to help Neftis.  The last thing that we need is the Shadow Council establishing a strong point right on our doorstep!\n\n{name}, you've earned yourself something nice.  Go ahead, take your pick.", objectives = "Kill 10 Shadowy Executioners, 10 Shadowy Summoners and Shadowmaster Grieve, and then return to Advisor Faila at Stonebreaker Hold in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10044] = { id = 10044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Visit With the Greatmother", description = "The Greatmother has asked that I seek you out and deliver a message. She wishes to speak with you at once.\n\nMy will has been sapped but make no mistake, {name}, if you anger the Greatmother, I will come down upon you with all the force that I can muster. She is in the main hall.\n\n<Garrosh points at the large building to the north.>\n\nListen to what she has to say and do as she tells you.", completion = "We must first expand your mind so that you may commune with the ancestors.", objectives = "Speak to Greatmother Geyah and listen to what she has to tell you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10045] = { id = 10045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Material Components", description = "Mother Kashur wishes to speak with you, {name}. Before this becomes possible, you must collect the herbs required to create a potion that will expand your mind, allowing you to commune with the spirits.\n\nYou must gather Olemba root from Terokkar, marshberries from Zangarmarsh, Telaari fronds from Nagrand and dragonspine from the Blade's Edge mountains. I have written down instructions on this parchment as to the cultivation of these herbs. Return to me when you have gathered the materials.", progress = "Hello, dear.", completion = "You are very resourceful, {name}. Our greatest gatherers would have taken twice as long to collect the herbs.\n\n\n\nDo not be afraid.", objectives = "Greatmother Geyah at Garadar in Nagrand has asked that you collect 1 Olemba Root, 1 Marshberry, 1 Telaari Frond and 1 Dragonspine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10046] = { id = 10046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Dark Portal", description = "Two weeks ago, our scouts reported a heavily armed Alliance force under the command of Field Commander Romus departing Nethergarde Keep. With so many soldiers and supplies, along with such a distinguished commander, they can only have one goal: Outland.\n\nThe warchief sent an advance force through the portal, but if the Alliance believes there is a need for that many troops, perhaps we'd be wise to send our own reinforcements.\n\nJourney through the Dark Portal and report to Nazgrel at Thrallmar.", sourceObjective = "Travel through the Dark Portal and speak with Nazgrel at Thrallmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10047] = { id = 10047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of Glory", description = "The 'Path of Glory,' they called it. A road leading from the heart of their gruesome fortress to the Dark Portal, paved with the bones of my people.\n\nIt wasn't enough for them to hunt us down like animals, destroy our cities, and torture those who survived. No, they had to use our bones as paving stones, denying my brethren a proper burial under the Light.\n\nThose tortured souls still wander these lands, crying out for release. I ask you, {name}, help me in this undertaking.", progress = "The cries seem somehow... fainter than they were before. The Light grant it's more than wishful thinking.", completion = "You have my sincere thanks for your efforts, {name}. Though much remains to be done, it gladdens me to know we have helped some find their long-deserved rest.", objectives = "Cleanse 8 Trampled Skeletons on the Path of Glory with Draenei Holy Water, then return to Warp-Scryer Kryv at Honor Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10048] = { id = 10048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Handful of Magic Dust", description = "I'm going to need dust, but not just any dust.\n\nThe royal teromoths that inhabit the forest nearby have a magical dust upon their wings, which they use to pacify those that hunt them.  I can make use of that property of the dust to assuage the resistance that I am feeling from the arakkoa eyes you retrieved.  This, in turn, will allow me to use them to find Deirom.\n\nI won't need much, perhaps half a dozen handfuls, or so.", objectives = "Collect 7 handfuls of Pacifying Dust for Andarl at the Allerian Stronghold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10049] = { id = 10049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Handful of Magic Dust", description = "I'm going to need dust, but not just any dust.\n\nThe royal teromoths that inhabit the forest nearby have a magical dust upon their wings, which they use to pacify those that hunt them.  I can make use of that property of the dust to assuage the resistance that I am feeling from the arakkoa eyes you retrieved.  This, in turn, will allow me to use them to find Dugar.\n\nI won't need much, perhaps half a dozen handfuls, or so.", objectives = "Collect 7 handfuls of Pacifying Dust for Kurgatok at Stonebreaker Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10050] = { id = 10050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unyielding Souls", description = "Near the end of our invasion, the Armory to the south fell under attack by the Horde's insidious Death Knights. Those vile shades cursed the Armory's defenders - and trapped their souls between the realms of the living and the dead.\n\nThose noble souls must be set free! I beg you, {name}, end my comrades' torment, for I have not the heart to slay them myself.", completion = "The Sons appreciate your efforts, even if few are willing to speak of the armory.", objectives = "Honor Guard Wesilow wants you to defeat 12 Unyielding Footmen, 10 Unyielding Sorcerers, and 5 Unyielding Knights at the Expedition Armory to the south.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10051] = { id = 10051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape from Firewing Point!", description = "Thank goodness for you!\n\n{class}, I need you to help me escape.  I have information vital to the security of the Allerian Stronghold and probably all of Outland!\n\nI came here from the Cenarion Expedition on a diplomatic mission, but as you can see, they weren't very friendly.  If you help me get to safety, I can assure you that you will be handsomely rewarded!", completion = "Isla Starmane just left, but she gave me a full rundown on what's going on out at Firewing Point.  It's understandable that she's quite distraught over what happened to the Cenarion Thicket.  Nasty blood elves!\n\nShe told me how you were instrumental in saving her so that we could get that information.  Allerian Stronghold is indebted to you for your service.\n\nPlease, accept this gift on behalf of us all.", objectives = "Escort Isla Starmane to safety and then report to Captain Auric Sunchaser at the Allerian Stronghold in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10052] = { id = 10052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape from Firewing Point!", description = "Thank goodness for you!\n\n{class}, I need you to help me escape.  I have information vital to the security of Stonebreaker Hold and probably all of Outland!\n\nI came here from the Cenarion Expedition on a diplomatic mission, but as you can see, they weren't very friendly.  If you help me get to safety, I can assure you that you will be handsomely rewarded!", completion = "Isla Starmane just left, but she gave me a full rundown on what's going on out at Firewing Point.  It's understandable that she's quite distraught over what happened to the Cenarion Thicket.\n\nShe told me how you were instrumental in saving her so that we could get that information.  Stonebreaker Hold is indebted to you for your service.\n\nPlease, accept this gift on behalf of us all.", objectives = "Escort Isla Starmane to safety and then report to Advisor Faila at Stonebreaker Hold in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10053] = { id = 10053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dealing with Zeth'Gor", description = "It is imperative that we follow up on the momentum created by your defeat of Warboss Nekrogg, {name}. If we're lucky, the leadership at Zeth'Gor won't have heard about Nekrogg.\n\nThe Bonechewers at Zeth'Gor to the southeast are usually led into battle by Grillok \"Darkeye\". Seek him out in his lair, a cave cut beneath the fel orc settlement, and kill him. Once he is dead, search the cave for the fel orc battle plans. We must not be taken by surprise.", objectives = "Defeat Grillok \"Darkeye\" and search his lair for the Bleeding Hollow Attack Plans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10054] = { id = 10054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Impending Doom", description = "A quick examination of the plans reveals Zeth'Gor's leader, Warlord Morkh, as the mastermind behind the attacks led by Bone Magus Warlor. There's more to the map than just Morkh's forces.\n\nThe plans indicate that the Bonechewer force is armed and marshalling for an all out attack on Honor Hold in concert with forces from Hellfire Citadel.\n\nThere's no time to bring word to Lieutenant Amadi. You must stop the Bonechewer forces before they can launch their attack!", objectives = "Slay 15 Bleeding Hollow Grunts, 10 Bleeding Hollow Necrolytes, 5 Bleeding Hollow Peons, and Warlord Morkh, then make your report to Lieutenant Amadi at Honor Hold's western tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10055] = { id = 10055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waste Not, Want Not", description = "Reinforcements are great, but I don't see 'em haulin' any wagons loaded with ingots or timber.\n\nTake a look around, friend. Trees are in short supply, and the mines are overrun with Legion scum.\n\nI'm in a bad way fer supplies, and I'm makin' what substitutions I can, but it's time to start reusing what we can.\n\nThe southern edge of the Path o' Glory is strewn with the ruins of siege machinery. Some pieces of 'em are still usable. Feeling up to a bit o' a salvage operation?", progress = "Were you able to find any usable materials out there underneath all the dust, ash, and char?", completion = "This is in better condition than I thought it'd be. Sure, it's going to take some time to work off all the rust, the char, and the like, but I'll not complain.", objectives = "Bring 8 pieces of Salvaged Metal and 8 pieces of Salvaged Wood to Dumphry at Honor Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10056] = { id = 10056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bleeding Hollow Supplies", description = "The orcish ruins of Zeth'Gor to the southeast serve as a base for an ever-growing tide of orcs emerging from Hellfire Citadel.\n\nThe Sons of Lothar have been fighting them for some time, and the stories they tell would be nigh unbelievable if I hadn't seen these 'fel' orcs with my own eyes.\n\nSomething has changed them, augmented them in a way we've never seen before. We have to do anything we can to keep them from strengthening. Go to Zeth'Gor and destroy any supplies you find there.", objectives = "Destroy 6 piles of Bleeding Hollow Supplies and report to Lieutenant Amadi at Honor Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10057] = { id = 10057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looking to the Leadership", description = "The disturbances at Expedition Armory continue, despite your best efforts. No one truly knows everything that happened there, nor exactly what binds the spirits of the fallen soldiers to the ruins.\n\nPerhaps we've been approaching this the wrong way. I've always assumed that each of the ghosts had a tie to the ruins, but what if their ties were to their leaders?\n\nArch Mage Xintor and Lieutenant Commander Thalvos were particularly close to their men, so perhaps overcoming their ghosts will calm the rest.", completion = "We can only hope that with the quieting of the ghosts of the officers, the spirits of the foot soldiers will follow. Thank you once again for your help, {name}.", objectives = "Overcome the ghosts of Arch Mage Xintor and Lieutenant Commander Thalvos and return to Honor Guard Wesilow in the tower northwest of Honor Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10058] = { id = 10058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Old Gift", description = "<The priest's gaze slowly moves from his mug to you.>\n\nDon't you know better than to bother a man in his cups?\n\nOh, what's the use? I suppose newcomers are a good sign. What would Turalyon think?\n\nI remember the eve of our departure, when I gave Mysteries of the Light to him. During the campaign and the ensuing years, he never forgot to read his daily passage to the men.\n\nWhen he left us again, he gave the book back to me. Like a fool, I believed it safe in my quarters to the south of the armory.", progress = "I thought I asked you not to bother me. What is it?", completion = "Is that really it? It's hard to believe it survived the battle. Conditions in the ruins haven't been kind to the book, but still, I'm glad to have it.\n\nIt's the only token I have of Turalyon.\n\n<Father Devidicus seems to be fighting back tears.>\n\nWhen you fight beside someone for so many years, they become closer than even family.", objectives = "Retrieve Mysteries of the Light and return it to Father Malgor Devidicus at Honor Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10059] = { id = 10059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dealing With Zeth'Gor", description = "It is imperative that we follow up on the momentum created by your defeat of Warboss Nekrogg, {name}. If we're lucky, the leadership at Zeth'Gor won't have heard about Nekrogg.\n\nThe Bonechewers at Zeth'Gor are usually led into battle by Grillok \"Darkeye\". Seek him out in his lair, a cave cut into the rock beneath the outpost, and kill him. Once he is dead, search the cave for the fel orc battle plans. Thrallmar must not be taken by surprise.", objectives = "Slay Grillok \"Darkeye\" and search his lair for the Bleeding Hollow Attack Plans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10060] = { id = 10060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Impending Doom", description = "A quick examination of the plans reveals Zeth'Gor's leader, Warlord Morkh, as the mastermind behind the attacks led by Bone Magus Warlor. There's more to the map than just Morkh's forces.\n\nThe plans indicate that the Bonechewer force is armed and marshalling for an all out attack on Thrallmar in concert with forces from Hellfire Citadel.\n\nThere's no time to bring word back to Thrallmar. You must stop the Bonechewer forces before they can launch their attack!", objectives = "Slay 15 Bleeding Hollow Grunts, 10 Bleeding Hollow Necrolytes, 5 Bleeding Hollow Peons, and Warlord Morkh. Then report to Stone Guard Ambelan at Spinebreaker Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10061] = { id = 10061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Unyielding", description = "When the Bonechewer fel orcs attacked the Expedition Armory, the garrison there fell quickly.  The battle was bloody and fierce, and there were no survivors.\n\nAlthough the dead were buried, their spirits continue to haunt those ruins.  Of late, I have been receiving visions that these spirits may soon become a threat to Thrallmar.\n\nThere is only one course of action to take.  We must grant these spirits rest.  You must overcome them in battle.", objectives = "Grelag wants you to defeat 12 Unyielding Footmen, 10 Unyielding Sorcerers, and 5 Unyielding Knights at the Expedition Armory to the south of Honor Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10062] = { id = 10062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looking to the Leadership", description = "The disturbances at the Expedition Armory continue, despite your best efforts. No one truly knows everything that happened there, nor exactly what binds the spirits of the fallen soldiers to the ruins.\n\nWe may be approaching this the wrong way. My visions suggested that each of the ghosts had a tie to the ruins, but what if their ties were to their leaders?\n\nArch Mage Xintor and Lieutenant Commander Thalvos were particularly close to their men, so perhaps overcoming their ghosts will calm the rest.", objectives = "Overcome the ghosts of Arch Mage Xintor and Lieutenant Commander Thalvos and return to Grelag at Spinebreaker Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10063] = { id = 10063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explorers' League, Is That Something for Gnomes?", description = "Babysitting! Would you believe it?\n\nThey pulled me out of a promising dig and sent me along with Captain Odesyus' expedition to babysit that little gnome!\n\nI'd never heard o' a gnome wanting to become a prospector before, so I asked.\n\nSeems we are takin' gnomes now, and this particular one has a fascination with murlocs!\n\nWell, he's gone off and set up shop in an old turtle shell on the northern shore of the island. Go and have a look if you don't believe me!", completion = "I thought so! That grumpy old dwarf was supposed to help me carry my equipment and gather data, but all he does is sit in that strange draenei town, drinking himself into a stupor.", objectives = "Find Clopper Wizbang camped in an old turtle shell on the shore north of Blood Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10064] = { id = 10064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talk to the Hand", description = "The Hand of Argus has established a forward base at Vindicator's Rest, but they are sorely outnumbered by both the blood elves and mutated wildlife. Without backup, their outpost is in danger of falling, and we'd have no way to keep an eye on events near the Vector Coil.\n\nReport to Scout Jorli at Vindicator's Rest to the northwest and offer her your assistance, {name}.", completion = "I was hoping Blood Watch would send reinforcements once they learned what we're up against.", objectives = "Report to Scout Jorli at Vindicator's Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10065] = { id = 10065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutting a Path", description = "During our mission to reconnoiter the Sunhawks and their portal, I sustained a serious wound. Scout Loryi has managed to staunch the bleeding and she's trying to figure out a way to evacuate me to Blood Watch.\n\nThe problem is that we'd have to abandon our position here in order to guarantee a safe return.\n\nAs soon as we leave this consecrated ground, we'll be set upon by ravagers. If you can clear some of the enraged ravagers, it might allow us to make the trip back safely.", completion = "It looks a bit better out there, but I still wonder if I wouldn't be better off waiting for a medic here.", objectives = "Kill 10 Enraged Ravagers and return to Scout Jorli at Vindicator's Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10066] = { id = 10066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, the Tangled Webs They Weave", description = "We don't dare abandon our post, or wander too far from Vindicator's Rest, {race}. The mutated creatures closest to the Vector Coil have been changed profoundly by energy leaking from the crystals.\n\nThe mutated tanglers appear to have gained a certain degree of sentience. They've learned to create, set, and conceal vicious traps that can ensnare even the most careful warrior.\n\nWe'll never be able to move against the Sunhawks if we're constantly forced to look underfoot. Attack the problem at its source, {name}.", completion = "Well done, {name}. It's going to be much easier to get reinforcements from Blood Watch, or launch strikes against the Sunhawks without having to worry about what the tanglers are up to.", objectives = "Kill 8 Mutated Tanglers and report to Vindicator Corin at Vindicator's Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10067] = { id = 10067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fouled Water Spirits", description = "Most of the creatures touched by the crystals' energy have been corrupted in the same ways: strange marks on their flesh, increased aggression, and small crystal shards in their bodies. However, the fouled water spirits north of here appear to be turning entirely to crystal.\n\nI've never seen anything react to the crystals this way before, when we explored the foul pool, they were particularly dangerous. We must get rid of them before the Sunhawks can exploit them as a new source of energy.", completion = "Well done, {name}. It's important not to overlook any opportunity to deny the Sunhawks sustenance.", objectives = "Kill 6 Fouled Water Spirits and return to Vindicator Corin at Vindicator's Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10068] = { id = 10068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frost Nova", description = "As you begin to grow in power, your connection to the arcane will develop, granting you access to new spells.\n\nGo, develop your power, and then demonstrate what you learn for me.", completion = "Ah good, a {class}. I've been expecting you.\n\nThere are a few tasks that I have which you are particularly suited to.", objectives = "Reach level 3 to learn Frost Nova. Locate a Training Dummy outside the Sunspire and practice using it 2 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10069] = { id = 10069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ways of the Light", description = "It is time for your first lesson in the ways of the Light, {name}. As you fight more battles, it will bring you closer to the light, and you'll start to uncover new abilities.\n\nGo, get more experience, and learn a new ability. Return and demonstrate it for me, and we'll continue your training.", completion = "Ah good, a {class}. I've been expecting you.\n\nThere are a few tasks that I have which you are particularly suited to.", objectives = "Reach level 3 to learn Seal of Command. Cast Seal of Command on yourself, then locate a Training Dummy outside the Sunspire and hit it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10070] = { id = 10070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steady Shot", description = "And now, it is time for your first lesson.\n\nAs you become more skilled, you will begin to discover new techniques.\n\nGo out, get some more experience, and learn your first new ability. Once you do, go find a training dummy and practice your new skill.", completion = "Ah good, a {class}. I've been expecting you.\n\nThere are a few tasks that I have which you are particularly suited to.", objectives = "Reach level 3 to learn Steady Shot. Locate a Training Dummy outside the Sunspire and practice using Steady Shot 5 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10071] = { id = 10071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evisceration", description = "As you grow in power, you'll start to figure out the tricks of the trade.\n\nOne of the first things you'll probably figure out is how to Eviscerate your enemy after landing some initial attacks.\n\nGet some experience, learn how to do it, and then find one of the training dummies outside and give it a try.", completion = "Ah good, a {class}. I've been expecting you.\n\nThere are a few tasks that I have which you are particularly suited to.", objectives = "Reach level 3 to learn Eviscerate, then locate a Training Dummy outside the Sunspire and practice using Eviscerate 3 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10072] = { id = 10072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning the Word", description = "As you grow in skill, so will the array of powers that you can call upon.\n\nI'd like you to go, continue to become more experienced, and discover a new spell. Once you do, come back and demonstrate it for me.", completion = "Ah good, a {class}. I've been expecting you.\n\nThere are a few tasks that I have which you are particularly suited to.", objectives = "Reach level 3 to learn Shadow Word: Pain. Practice casting it 5 times on nearby training dummies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10073] = { id = 10073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corruption", description = "By now, you've heard the rumors about our kind, the warlocks. Pay them no mind; they are uttered by those jealous of our fearsome powers.\n\nAs you become more experienced, you will uncover mysteries of controlling fel energies. \n\nGo, continue your journey until you uncover a new technique. I want you to practice using this new spell on the training dummies outside the Sunspire.", completion = "Ah good, a {class}. I've been expecting you.\n\nThere are a few tasks that I have which you are particularly suited to.", objectives = "Reach level 3 to learn Corruption. Locate a Training Dummy outside the Sunspire and practice casting Corruption 5 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10074] = { id = 10074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oshu'gun Crystal Powder", description = "This base was the primary draenei research facility for the study of naaru crystals.\n\nWhat we have discovered is a veritable goldmine of research notes about the crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this region carries with it some residual powder of the Oshu'gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster.", progress = "The crystalline powder from the mountain is infused within the earthen core of this region.", completion = "Wonderful, {name}. This will help us in our battle against the Alliance filth that have surfaced in the Outland.", objectives = "Chief Researcher Amereldine at Halaa wants 10 Oshu'gun Crystal Powder Samples.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10075] = { id = 10075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oshu'gun Crystal Powder", progress = "This base was the primary draenei research facility for the study of naaru crystals.\n\nWhat we have discovered is a veritable goldmine of research notes about the crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this region carries with it some residual powder of the Oshu'gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster.", completion = "This base was the primary draenei research facility for the study of naaru crystals.\n\nWhat we have discovered is a veritable goldmine of research notes about the crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this region carries with it some residual powder of the Oshu'gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster." }
quests[10076] = { id = 10076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oshu'gun Crystal Powder", description = "This base was the primary draenei research facility for the study of naaru crystals.\n\nWhat we have discovered is a veritable goldmine of research notes about the crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this region carries with it some residual powder of the Oshu'gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster.", progress = "The crystalline powder from the mountain is infused within the earthen core of this region.", completion = "Wonderful, {name}. This will help us in our battle against the Horde filth that have surfaced in the Outland.", objectives = "Chief Researcher Kartos at Halaa wants 10 Oshu'gun Crystal Powder Samples.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10077] = { id = 10077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oshu'gun Crystal Powder", progress = "This base was the primary draenei research facility for the study of naaru crystals.\n\nWhat we have discovered is a veritable goldmine of research notes about the crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this region carries with it some residual powder of the Oshu'gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster.", completion = "This base was the primary draenei research facility for the study of naaru crystals.\n\nWhat we have discovered is a veritable goldmine of research notes about the crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this region carries with it some residual powder of the Oshu'gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster." }
quests[10078] = { id = 10078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Laying Waste to the Unwanted", description = "Now that we've gotten our salvage operation off the ground, it's time to begin the second phase of the plan.\n\nAcross the Path of Glory, the Horde still has their old blade throwers trained on us. Don't let their age fool you, {name}, they're still very dangerous. Much as we're working to reclaim what we can, we can't assume the Horde is going to dismantle their weaponry.\n\nTake this torch and burn the remaining siege equipment. I'll take no chances with Honor Hold's safety.", completion = "That's the spirit!\n\nI'm glad we finally got some reinforcements, but I'm not so sure about their attitude toward the Horde. Where I come from, anyone with a weapon pointed at you is an enemy and needs to be dealt with like one!", objectives = "Use the Flaming Torch to burn the Horde Blade Throwers overlooking the Path of Glory. Then, bring the Flaming Torch to Dumphry in Honor Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10079] = { id = 10079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When This Mine's a-Rockin'", description = "The mine's been overrun by a plague of gan'arg misfits!\n\nNot only did they run all my workers out of the tunnels, but they're pounding away in there night and day! To make things worse, now I've got Danath on me back! He says he's going to take away me ale ration if I don't get this taken care of soon!\n\nNone of the miners'll go in there, and the guards are busy drinking themselves silly.\n\nI'm begging you, {name}, help me here. Danath can take me dignity, but he'll never take me ale!", completion = "By Bronzebeard's bronze... beard, you've done it! You're a hero, {name}.", objectives = "Kill 12 Gan'arg Sappers and return to Foreman Biggums.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10080] = { id = 10080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forge Camps of the Legion", description = "If you've spoken to Humphry, he's undoubtedly told you that he finds the infestation in the mines a minor annoyance, but I know it for what it is: a symptom of a larger evil.\n\nTo the northeast of the Horde outpost of Thrallmar, the Legion's minions labor night and day on something, but what is it?\n\nNone of the scouts I've dispatched to the camps have ever returned. The time for subtlety has passed, {name}. Fight your way into Forge Camp: Rage and find out just what the Legion is up to.", objectives = "Kill 10 Gan'arg Servants, 5 Forge Camp Legionnaires, and 5 Sisters of Grief, then search Forge Camp: Rage for evidence of the Legion's intentions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10081] = { id = 10081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Meet Mother Kashur", description = "Do not be alarmed by what you might see once the effect has taken hold! These spirits are all around us - always. The potion allows your mind to be able to understand and ultimately see the spirits. You will need to be under its influence if you are to speak with Mother Kashur.\n\nYou will find her a great ways to the southwest, at the Ancestral Grounds.", completion = "The potion that you drank has no real effect. You can only see a spirit if they allow it. The potion is merely a symbol of your belief and dedication. It was a test and you passed...", objectives = "Greatmother Geyah wants you to speak with Mother Kashur.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10082] = { id = 10082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Agitated Ancestors", description = "Do you see them walking around us? The Ancestral Grounds are normally quiet and undisturbed.\n\nAs of late, the ancestral spirits have risen and are extremely agitated. Something is causing a great disturbance to the spirits. We must discover what that something could be, but first, we must put the immediate threat to rest.\n\nThese ghosts that you see walking about are not truly the ancestors but a representation of their state of being. You must destroy the agitated orc spirits. Do this and return to me.", completion = "It's no use. They continue to rise. There must be something more insidious underway.", objectives = "Mother Kashur has asked that you put to rest 8 Agitated Orc Spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10083] = { id = 10083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legion's Plans", description = "You make a copy of the glowing glyphs etched into the ground, but without the second half, the diagram doesn't make sense.\n\nField Marshall Rohamus mentioned another camp to the west, Forge Camp: Spite. Could that be where the Legion is keeping the other half of the plans?\n\nIf the Legion has undertaken a massive production campaign, assembling at multiple sites would make sense.", objectives = "Retrieve the Forge Camp: Spite Plans and return them to Field Marshal Rohamus at Expedition Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10084] = { id = 10084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Mageddon", description = "With the skills of the mo'arg engineers and an endless supply of their gan'arg minions, they'll begin churning out fel reavers before we can get word to Nethergarde.\n\nWe have no choice but to move against them as soon as possible. We cannot strip Honor Hold's defenses to support you in this offensive, for to do so would be suicide. The fel orcs and the Horde will pounce on us at the first sign of weakness.\n\nHonor Hold has stood for 20 years, and we don't intend to lose it now.You will be able to choose one of these rewards:", objectives = "Kill Nightlord Malphas at Forge Base: Mageddon, and report to Force Commander Danath Trollbane at Honor Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10085] = { id = 10085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Visit With The Ancestors", description = "I need for you to journey to the villages of the ancestors, {name}. Seek each one out and see if the ancestors remain.\n\nVisit Sunspring Post to the north, visit the Laughing Skull Ruins far to the north against the mountains, visit Garadar to the northeast, and finally, visit the Bleeding Hollow Ruins on the borders of Nagrand and the Terokkar Forest, to the east.\n\nReturn to me once you have observed the ancestors in their homes.", progress = "Move as the wind, {name}.", completion = "This is very troubling. You say that none of the ancestors were at their villages? That they were all moving south?", objectives = "Mother Kashur at the Ancestral Grounds in Nagrand has asked that you Visit Sunspring Post, Visit Laughing Skull Ruins, Visit Garadar and Visit Bleeding Hollow Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10086] = { id = 10086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Work... For the Horde!", description = "Would you believe it?  These orcs hired me to help them shore up damaged fortifications and build explosives.  What a dream job!  It's too bad we're so short on materials, but a clever goblin like myself learns how to make do!\n\nCan you help me?  I need salvaged wood and metal from the ruined battlements along the Path of Glory.  Go down there and salvage, and watch out for those red-skinned orcs!\n\nWhen you're done, come back for big rewards!", progress = "So how did the salvage mission go?  Did you find anything useful?", completion = "This stuff is great!  A little bent and a little burnt, but I've never let low grade materials stop me from making precision high explosives.\n\nThanks, {name}.  You really have an eye for quality trash!", objectives = "Bring 8 pieces of Salvaged Metal and 8 pieces of Salvaged Wood to Megzeg Nukklebust in Thrallmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10087] = { id = 10087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burn It Up... For the Horde!", description = "I'm a lucky, lucky goblin.  I get to make explosives and killing machines, knowing they'll be used immediately on important missions!\n\nSpeaking of missions, I just got one from Thrallmar command: burn the Alliance cannons on the far side of the Path of Glory... the ones pointing dangerously close to Horde fortifications.  Take this torch and make your way to each cannon.  Fire the torch and watch the sparks fly!", progress = "I've been looking for the telltale signs of burning cannons -- smoke plumes, or the cries of burning fel orcs...\n\nAny luck on your mission?", completion = "I thought so!  I couldn't quite make out the destruction from here, but I can imagine how it must have looked.  Splendid!\n\nWell done, {name}.  Thrallmar command will be happy to hear of your success!", objectives = "Use the Flaming Torch to burn the Eastern Alliance Cannon and the Western Alliance Cannon, and then return to Megzeg Nukklebust in Thrallmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10088] = { id = 10088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When This Mine's a-Rockin'", description = "The mine's been overrun by a plague of gan'arg misfits, and on top of that, the peons have decided that this is a fine time for a nap! I don't know how they can sleep through all the disturbances coming from the mine, but that's the least of my problems.\n\nIf we don't get rid of those gan'arg pests soon, Thrallmar's supply of ore and other minerals will be cut off. I've already asked Watch Commander Krunk for help, but he says he can't spare the men with the town under constant attack. Will you help?", objectives = "Kill 12 Gan'arg Sappers and return to Foreman Razelcraz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10089] = { id = 10089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forge Camps of the Legion", description = "Thrallmar has been subjected to bombardment from the Legion Camps since its establishment. We've managed to hold out so far, but the situation is getting more desperate with every day.\n\nShadow Hunter Ty'jin has made several attempts to learn more about the camps, but none of his scouts ever returned.\n\nThe time for subtlety has passed, {name}. Fight your way into Forge Camp: Rage and find out just what the Legion is up to.", objectives = "Kill 10 Gan'arg Servants, 5 Forge Camp Legionnaires, and 5 Sisters of Grief, then search Forge Camp: Rage for evidence of the Legion's intentions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10090] = { id = 10090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legion's Plans", description = "You make a copy of the glowing glyphs etched into the ground, but without the second half, the diagram doesn't make sense.\n\nThe glyphs indicate that another camp to the west, Forge Camp: Spite, is also involved in the project. Could that be where the Legion is keeping the other half of the plans?\n\nIf the Legion was forging something truly monstrous, assembling it at multiple sites would make sense.", objectives = "Retrieve the Forge Camp: Spite Plans and return them to Overlord Hun Maimfist at Reaver's Fall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10091] = { id = 10091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Soul Devices", description = "Gah!  They've been torturing me, trying to get me to tell them everything that I know.\n\nI failed - they fed the others to Hellmaw, and I was to be next.  But I told them nothing!\n\nThey're crazy!  They're hell-bent on summoning demonic forces that they have no way of controlling!\n\nThey're using special devices to make their soul shards, and their summoning, more powerful.  You must steal these devices!\n\nI would join you, but I must return to Shattrath City to report to the Lower City's spymistress.", progress = "Yes?  What can I do for you, {class}?", completion = "To'gun was here earlier giving me his report.  He should have stayed with you to help!\n\nI sent him back out there to assist Grik'tha.  I think they make a cute couple.\n\nSo, these are the soul devices that the Shadow Council were using to enhance their summoning power?  They look dangerous to me - maybe the Scryers will know what to do with them?\n\nPlease, take one of these as a reward for crippling the Shadow Council's operation in the labyrinth.", objectives = "Steal 5 Soul Devices and deliver them to Spymistress Mehlisah Highcrown at the Terrace of the Light in Shattrath City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10092] = { id = 10092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Mageddon", description = "With the skills of the mo'arg engineers and an endless supply of their gan'arg minions, they'll have churned out a fleet of fel reavers before we can get word to Orgrimmar.\n\nWe have no choice but to move against them as soon as possible. I cannot use Thrallmar's garrison to support you, since it would leave us too vulnerable.\n\nThere are any number of opportunists, the Alliance notwithstanding, who would eagerly pounce on our unprotected outpost. Do not fail, {name}. Too much depends on you.You will be able to choose one of these rewards:", objectives = "Kill Nightlord Malphas at Forge Base: Mageddon, and return to Overlord Hun Maimfist at Reaver's Fall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10093] = { id = 10093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Temple of Telhamat", description = "Fortunately, the Path of Glory is not the only trace of my people in these lands. To the west, a few of our holy sites survive, although some have been overrun.\n\nWhile Velen prepared for the journey that would lead him to Azeroth, those of us who would remain behind sought to reestablish a presence at our holy places.\n\nIn the western part of the Hellfire Peninsula, you will find a small group of draenei at the Temple of Telhamat, led by Amaan the Wise. I am certain he'd be interested in meeting you.", completion = "Ah, so you've met Seer Kryv. He is a wise and gifted man and any {race} he would name a friend is also a friend of mine.\n\nMake yourself comfortable and introduce yourself to the others who call the temple home.", objectives = "Speak with Amaan the Wise at the Temple of Telhamat in western Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10094] = { id = 10094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Codex of Blood", description = "It has been two years since the Shadow Council summoning that resulted in the explosion of this once-great mausoleum, and the formation of the Bone Wastes.\n\nNow they are at war with an unbelievably powerful force on the inside.\n\n{name}, you must make your way into the Shadow Labyrinth to determine what they are up against, and to see if it poses a threat to us.  Our spies speak of their use of a forbidden book of unholy summoning, known only as the Codex of Blood.\n\nSeek your answers within its pages.", completion = "Opening the magically-suspended tome, a sense of dread overwhelms you.\n\nSomething is most definitely wrong here!\n\nYou read on, but what you read seems unbelievable!", objectives = "Read from the Codex of Blood in the Shadow Labyrinth of Auchindoun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10095] = { id = 10095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Heart of the Labyrinth", description = "The Shadow Council has lost control of the cosmic being that they summoned here almost two years ago!  It is what caused the explosion of Auchindoun, and the creation of the Bone Wastes beyond.\n\nKnown only as Murmur, it threatens to overrun the Shadow Council and break free into the outside world!\n\nWith the grandmaster, and the rest of their leadership dead, you are Outland's last hope against this monstrosity!\n\n{name}, you know at the core of your being that you and your companions dare not fail!", completion = "Murmur almost broke free?!  They've had that thing contained in there for two years... I wonder what they did wrong to lose control over it after all this time?\n\n{name}, by putting that beast down you've likely saved all of us!  I cringe to think what would have happened to all of us here, and the rest of Outland, if that thing had somehow managed to break free!\n\nI'm glad you helped us to take matters into our own hands and deal with the Shadow Council threat at Auchindoun.  How can we ever reward you?", objectives = "Destroy Murmur and inform Spymistress Mehlisah Highcrown at the Terrace of Light in Shattrath City of the events that have transpired inside the Shadow Labyrinth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10096] = { id = 10096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving the Sporeloks", description = "Ikeyen's been telling me stories about what happened to him down in those caves and I think it's just awful!\n\nYou know, maybe we should do something to help out those poor sporeloks.  Ikeyen says that they live there in the Funggor Cavern, but that the marsh beasts have recently invaded.\n\nWhy don't you go down there and see if you can clear some of those marsh beasts out?  It's just to the southwest.", completion = "Good!  Those marsh beasts have no right to invade the home of the sporeloks!\n\nIt would be better if these creatures would learn to live in harmony, but when that's not possible, we'll be here to take care of the situation!\n\nHere, please take one of these as thanks for your help.", objectives = "Slay 10 Marsh Dredgers and 10 Marsh Lurkers, and then return to Lauranna Thar'well at the Cenarion Refuge in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10097] = { id = 10097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brother Against Brother", description = "The Sethekk departed Skettis with great fanfare when Auchindoun exploded. Surely it must've been an omen of our master's arrival.\n\nMy brother, Syth, was one of their leaders and told us we were obligated to go into the temple ruins and face our god.\n\nAfter we took up residence in the ruins, calling them the Sethekk Halls, I began to doubt my brother and his ally, Ikiss.\n\nIn time, Syth had me cast out of the Halls, but he refused to let me take our sister Lakka with me. Will you help me rescue her?", completion = "I can't thank you enough, {name}. Knowing that Lakka is free means I can cut the rest of my ties to the Sethekk.\n\nPart of me will never forgive myself for Syth's death, but it had to be done. When I reach Skettis, I will perform the death rites for him. Perhaps his spirit will find rest once it has atoned for leading our people astray.", objectives = "Kill Darkweaver Syth in the Sethekk halls, then free Lakka from captivity. Return to Isfar outside the Sethekk halls when you've completed the rescue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10098] = { id = 10098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terokk's Legacy", description = "My people honor an ancient hero named Terokk. Arakkoa hatchlings are regaled with stories of his deeds and descriptions of his beautiful plumage.\n\nHe dwelt among my people for hundreds of years, but mysteriously vanished one day, leaving only his mask, spear, and writings behind.\n\nThe relics are cherished by the arakkoa, but they were heartbroken when the Sethekk bore the objects away from Skettis at their departure.\n\nI have written down what little I know about their location within the halls.", progress = "The relics of Terokk have been absent from Skettis for too long. Were you able to recover them from the Sethekk?", completion = "I may never truly be forgiven for my role in the crimes of the Sethekk, but perhaps by restoring the relics of Terokk to my people, I can begin to redeem myself.\n\nThank you for helping me in this, {name}. You have no idea of the magnitude of what you've done this day.", objectives = "Bring Terokk's Mask, Terokk's Quill, and the Saga of Terokk to Isfar outside the Sethekk Halls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10099] = { id = 10099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mastermind", description = "Those infernal gan'arg keep scurrying into the mine! For each one you kill, two or three more seem to take its place!\n\nThere's got to be someone down there in the deepest reaches of the mine directing the incursion. You seemed to do well against them last time, and Light knows you're the only one brave enough to venture back into the mine. Find out who's responsible for this disturbance and make him pay!", progress = "I'm almost afraid to ask. Seeing you come out of the mine alive means one of two things: either you killed the monster, or you lost your nerve. Well, which is it?", completion = "I'm glad you managed to take care of, of... what did you say he called himself? Z'kral?\n\nFrom your description, it sounds more like an 'it' than a 'him' but all that matters is it's dead.", objectives = "Locate and kill Z'kral in the mines beneath Honor Hold, then report back to Foreman Biggums.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10100] = { id = 10100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mastermind", description = "Don't get me wrong, {name}, I'm glad that you agreed to help with the mines, but for every sapper you killed, I swear two more appeared.\n\nI've been giving Watch Commander Krunk an earful, but he's still refusing to send me any help. He keeps muttering something under his breath about helboars. If I wasn't so sure he'd hit me, I'd tell him this is no time to be thinking about ribs!\n\nAnyway, it looks like there's someone down there deep in the mines directing this whole thing. Find him and kill him!", objectives = "Locate and kill Urga'zz within the mines beneath Thrallmar, then return to Foreman Razelcraz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10101] = { id = 10101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Spirits Speak", description = "Oshu'gun - the diamond mountain - was once sacred to my people. It was there that the clans would gather every year to celebrate the springtime festival. It was there that our shaman communed with the honored ancestors. It was the center of our culture - until the shadows overtook us. When the clans became a horde, the spirits of Oshu'gun fell silent. The ancestors turned their backs on us.\n\nYet something now draws them from their rest. Venture to Oshu'gun and discover what could trouble the spirits so.", completion = "<A gentle, melodic voice fills your mind.>\n\nI am K'ure of the naaru, {name}. You stand within the heart of my ancient vessel. \n\nOshu'gun, as the orcs named it, is the ship that first brought the draenei to this world.  Though we fell from the heavens and crashed here many hundreds of years ago, my weakened energies have remained trapped within this wreckage. Regrettably, I am the source of the orc spirits' pain.", objectives = "Mother Kashur at the Ancestral Grounds in Nagrand has asked that you seek out the vision you had. Find K'ure in Oshu'gun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10102] = { id = 10102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Secret Revealed", description = "As my energies bled away over the centuries, a void slowly grew in my place - devouring the souls of those nearby. Helplessly, I watched as generations of orc souls were drawn into the vortex. Recently, my enemies harnessed the vortex and used it to draw countless void minions into their Burning Legion.\n\nNow, the key to ending this cycle and freeing the orc spirits lies with another naaru - A'dal. I have sensed his essence within the ancient city of Shattrath in the Terokkar Forest.", completion = "K'ure was wise to send you here. While we cannot assist you with the suffering of the orc ancestors, there is one that can.\n\nOne that is soon to be reborn of Light...", objectives = "Speak with A'dal in Shattrath City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10103] = { id = 10103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Zurai", description = "With the arrival of Field Commander Romus and his forces, the Alliance and their draenei friends have grown bold. They're militarizing every old draenei ruin from here to Shattrath.\n\nIn response, the trolls have established a new outpost in the eastern part of Zangarmarsh, just south of the Dead Mire. Swamprat Post, they're calling it. I'm glad they have a sense of humor about living in a place like that, because I wouldn't relish it.\n\nThe post's commander has asked me to send anyone I can spare.", completion = "To be honest, I had expected more, but you'll have to do. Welcome to Swamprat Post.", objectives = "Report to Zurai at Swamprat Post in Zangarmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10104] = { id = 10104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Concerns About Tuurem", description = "The rumors from Tuurem are unsettling. Some say the town's ruins are overrun with crazed Broken and Lost Ones, while opportunistic artifact hunters steal draenei relics.\n\nIt's hard to know which are true and which aren't, but we have a responsibility to safeguard the ruins as best we can. Find Andarl at the Allerian Stronghold in Terokkar Forest. He is something of a student of magical relics. More than anyone else, he's likely to know what's going on there.", completion = "I'm flattered that your Broken friend considers me a scholar of his people's relics, but to be honest, I haven't had much chance to study them since my arrival here. It was certainly my intent, but when I arrived, I found that there were other matters that required my attention.", objectives = "Speak with Andarl at the Allerian Stronghold in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10105] = { id = 10105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "News for Rakoria", description = "Now that Swamprat Post is complete, our control of the roads in and out of the marsh is much less tenuous. Our presence in Terokkar Forest is much less secure. Even so, at Stonebreaker Hold, Rakoria awaits word of our progress.\n\nShe's sharp and capable, {name}, but be careful around her. She's got a lot of goods she's eager to move along the roads, but don't assume she's got our best interests at heart. Rakoria goes where she believes there's profit to be found.", completion = "I'd hoped his men would have the outpost complete sooner, but it's not costing him money. Still, it's progress.", objectives = "Speak with Rakoria at Stonebreaker Hold in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10106] = { id = 10106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Fortifications", description = "The Hellfire Citadel wages constant battles with our forces.  We are holding our own so far, but we can't yet launch a real offensive against them.  To do that, we need forward staging areas.\n\nOur scouts identified three fortifications near Hellfire Citadel.  We want you to help secure these forts.  Capture each fort, and then report back to me.\n\nMay fortune shine upon you in the conflicts ahead, {name}, for you will no doubt clash with Horde forces eager to gain these same fortifications.", completion = "Well done, {name}.  Your actions in the field are instrumental in our battle for Hellfire Peninsula.", objectives = "Capture the Overlook, the Stadium and Broken Hill, then return to Warrant Officer Tracy Proudwell in Honor Hold in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10107] = { id = 10107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomatic Measures", description = "Kilrath sends news of the Boulderfist leader: He is an orc! An ancient orc that passed through the Dark Portal in the time of our fathers and has since returned to his homeland. I wish for you to track down this orc and try to convince him to pull back the Boulderfist ogres. He resides on an upper platform in the Burning Blade Ruins to the southeast near the border of Terokkar. Good luck, {name}!\n\nBe warned, he is a blademaster...", progress = "Speak.", completion = "So what is your decision? Will it be war or will you lend your assistance?", objectives = "Jorin Deadeye at Garadar in Nagrand has asked that you find and speak with Lantresor of the Blade in the Burning Blade Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10108] = { id = 10108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomatic Measures", description = "The huntress's agents send news of the Boulderfist leader: He is an orc! An ancient orc that passed through the Dark Portal in the time of our fathers and has since returned to his homeland. I wish for you to track down this orc and try to convince him to pull back the Boulderfist ogres. He resides on an upper platform in the Burning Blade Ruins to the east. Good luck, {name}!\n\nBe warned, he is a blademaster...", progress = "Speak.", completion = "So what is your decision? Will it be war or will you lend your assistance?", objectives = "Mo'mor the Breaker at Telaar in Nagrand has asked that you find and speak with Lantresor of the Blade in the Burning Blade Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10109] = { id = 10109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Must Have Them!", description = "Do you see them?? By Gazlowe's horrific halitosis, I will have those eggs! Say, you look like you might be of some use.\n\nI'll tell you what, {race}; if you gather a few items for me to make my Jump-a-tron 4000 functional, I'll give you a key that will let you operate the machine as well! What can you do with a Jump-a-tron 4000 you say? What can't you do is more like it...\n\nI'll need air elemental gas from the air elementals of Nagrand. They're all over the place so don't ask me where to find 'em!", progress = "Got gas?", completion = "Excellent! Now just a few adjustments and this thing will be as good as new. Oh yes, your key! Here you go.\n\nBy the way, the Jump-a-tron still has a few kinks that I need to work out. Um, just be careful.", objectives = "Wazat across from Clan Watch in southern Nagrand wants you to bring him 3 Air Elemental Gases.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10110] = { id = 10110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Fortifications", description = "The fel orcs of Hellfire Citadel must be scoured from our birthland!  To attack them, we must first secure forward staging points near the Citadel.\n\nOur outrunners found three fortifications that will suit this purpose, but the Alliance has the same idea and even now sends forces to take them!\n\nWe want you to stop the Alliance and capture these forts.  Aid in the capture of each fort and then return to me.\n\nFor the Horde!", completion = "Nice work, {name}.  I could almost hear the battles waged at those forts.  I wish I was there to see them!", objectives = "Capture the Overlook, the Stadium and Broken Hill, then return to Battlecryer Blackeye in Thrallmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10111] = { id = 10111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Me The Egg!", description = "Now that you've been initiated, I want you to get me that egg! Use the Jump-a-tron and try to hit the nest dead center. But be careful! Bodily injury or serious permanent damage may occur from a bad jump.", progress = "Did I mention my love for eggs?", completion = "Well, it's no egg... Hey! I love chicken too! I'll just chomp right through this ginourmous talon! Thanks!", objectives = "Wazat in Nagrand wants you to use the Jump-a-tron 4000 to get to the nest in the nearby tree and steal the Mysterious Egg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10112] = { id = 10112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Personal Favor", description = "Hmmm?  A box you say?  Or was it several?  Do you know what material the box was constructed from?\n\nAnd what was the name of this merchant?  Empoor?  Are you certain that he's one of the Broken?  I don't do much business with their kind.\n\nPerhaps my memory would be jogged if you were to do me a favor?\n\nThe Skithian arakkoa - primitive casters that they are - recently stole a huge shipment of my more exotic goods.  I want it all back!\n\nYou can find Veil Skith just to the south of Shattrath City.", progress = "Hmm, is my memory improving?", completion = "Yes, indeed, I do believe that it's all getting clearer now.\n\nAnd I think that your diligence in this matter deserves more than just the information that you seek.", objectives = "Retrieve 5 of Lathrai's Stolen Goods. Return them to Wind Trader Lathrai near the World's End Tavern in the Lower City section of Shattrath City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10113] = { id = 10113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nesingwary Safari", description = "\"Go out and find us some supplies,\" he said. I was nearly killed about 15 times before I found this place! These Broken might not be the most hospitable bunch but at least they're not trying to tear my skin from my bones.\n\nAnyway, I'm not going back. My days of huntin' big game are over. If you end up heading northeast towards Zangarmarsh and run into the Nesingwary Safari, let them know that \"Shotgun\" quit. \n\nHey, maybe you can take my place! Good luck, stranger.", completion = "I suppose we'll have to find a replacement water boy. Say, you look like a powerful {class}. Interested in a job? Or did you come for the hunt?", objectives = "\"Shotgun\" Jones wants you to speak with Hemet Nesingwary at the Nesingwary Safari on the outskirts of northeast Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10114] = { id = 10114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nesingwary Safari", description = "These orcs have never seen a tauren before - if you can believe such a thing. If it weren't for Captain Kroghan, they would have probably been serving me for their next meal right about now.\n\nBut where are my manners? I am Ohlorn Farstrider, hunter extraordinaire! I am part of the Nesingwary expedition that came up here from Azeroth in search of big game. If you are interested in the hunt, perhaps you should visit my crew at the Nesingwary Safari, due east of here near the border of Zangarmarsh.", completion = "I am relieved to hear that he is safe. Have you come to join the hunt?", objectives = "Ohlorn Farstrider wants you to speak with Shado 'Fitz' Farstrider at the Nesingwary Safari in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10115] = { id = 10115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daggerfen Deviance", description = "The Kurenai and the draenei don't always see eye to eye, particularly on the issue of the Lost Ones. We are content to help the Lost Ones who seek us out, but we won't pursue them. Some draenei are intent on 'redeeming' them all.\n\nHowever, there are times when even the Lost Ones go too far, such as the Daggerfen. In their village to the west, they dabble in poisons and deceit, arts that come unnaturally to us.\n\nWe must put an end to this before the vile Daggerfen can extend their influence.", completion = "You have done well, {name}. The Daggerfen are beyond redemption by anyone's standards, but I'm not certain that the draenei would've acted with the proper speed in this situation.", objectives = "Slay 3 Daggerfen Assassins and 15 Daggerfen Muckdwellers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10116] = { id = 10116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Chieftain Mummaki", description = "Wanted: Chieftain Mummaki - leader of the foul and degenerate Lost One tribe of the Daggerfen, for his brutal attacks against the Orebor Harborage.\n\nThe chieftain and his band of assassins are responsible for the deaths of numerous Kurenai and draenei and should only be approached by seasoned combatants.\n\nTravelers are advised to avoid the Daggerfen Village area to the west of the Orebor Harborage.\n\nTo claim the bounty, present proof of the chieftain's demise to Ikuti.", progress = "So you wish to claim the bounty on Chieftain Mummaki?", completion = "Remarkable! There have been others who tried to claim the bounty, but they never returned. It's not hard to figure out what happened to them.\n\nI'm relieved that we'll no longer be troubled by Mummaki and his degenerates.", objectives = "Bring Chieftain Mummaki's Totem to Ikuti at the Orebor Harborage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10117] = { id = 10117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Chieftain Mummaki", description = "Wanted: Chieftain Mummaki - leader of the foul and degenerate Lost One tribe of the Daggerfen, for his brutal attacks against Zabra'jin and its inhabitants.\n\nThe chieftain and his band of assassins are responsible for the deaths of numerous scouts and messengers and should only be approached by seasoned combatants.\n\nTravelers are advised to avoid the Daggerfen Village area to the northwest of Zabra'jin.\n\nTo claim the bounty, present proof of the chieftain's demise to Shadow Hunter Denjai.", progress = "So you wish to claim the bounty on Chieftain Mummaki?", completion = "You have my thanks, {name}. I was beginning to think that I was going to have to take a substantial part of the garrison up there and deal with Mummaki myself. Of course, there's no telling what might have happened to Zabra'jin then.", objectives = "Bring Chieftain Mummaki's Totem to Shadow Hunter Denjai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10118] = { id = 10118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Message to the Daggerfen", description = "Of all the Lost One tribes in Zangarmarsh, the Daggerfen are the most cunning and most aggressive. They are highly organized and make no secret of the fact that they desire control over the other Lost Ones in the marsh.\n\nTheir attacks have already taken quite a toll on my scouts and messengers. I cannot afford to lose any more men.\n\nIf we don't act soon, they'll have complete control over the roads and Zabra'jin will effectively be surrounded.", completion = "I think you've managed to send a fairly strong message to them. Perhaps now, the rest of my men won't be so afraid to take the fight to the Daggerfen. Or, if they are, they'll find themselves ashamed by their lack of bravery.", objectives = "Slay 3 Daggerfen Assassins and 15 Daggerfen Muckdwellers and return to Shadow Hunter Denjai at Zabra'jin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10119] = { id = 10119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Crusade: Through the Dark Portal", description = "For 20 years the Dark Portal has remained a silent monument - a eulogy to a time long since forgotten.\n\n<Relthorn looks around.>\n\nI never thought to see this day, yet here we stand, looking into the abyss.\n\nOn the other side of this gate we are locked in a savage war - a war that we cannot win without support. You must go through the Dark Portal and help our troops, {class}.\n\nReport to Commander Duron at once. He awaits you in Outland...", completion = "Welcome to Outland, {name} -- welcome to the nightmare! Though the initial Expeditionary Force made it through unscathed, the Legion is attempting to retake the Dark Portal and prevent any of our reinforcements from coming through.\n\nAs much as I'd like your aid here, our troops and the Horde soldiers are able to fend off the Legion platoons that are attempting to take control of this platform.\n\nWe need you where your talents can best be utilized.", objectives = "Travel through the Dark Portal and find Commander Duron. He awaits your arrival on the other side - in the Outland.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10120] = { id = 10120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arrival in Outland", description = "Aided by the Alliance, my forces will hold the line here, but I need you to deliver my report to General Krakork in Thrallmar. With his help, we'll be able to drive these demons back into the abyss that spawned them! Speak to Vlagga Freyfeather. She'll speed you on your way.", progress = "I saw you speaking with Orion - it must be important business...", completion = "So you're Orion's new messenger? I pray you fare better than the last one he sent, {class}.  With the Legion pressing in, you'd never make it to Thrallmar on foot. Say the word, and my faithful wyvern will deliver you there safely.", objectives = "Lieutenant General Orion at the Dark Portal in Hellfire Peninsula wants you to bring Orion's Report to Vlagga Freyfeather.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10121] = { id = 10121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eradicate the Burning Legion", description = "Though this land is full of strange new enemies, the Burning Legion is still the greatest threat to our Expedition. One of my most trusted warriors, Sergeant Shatterskull, has been studying the Legion's tactics - trying to discern the demons' true purpose in this land. Seek him out at the supply caravan just outside the southern wall.\n\nAnd {name} - be wary of the Legion. Their evil cannot be underestimated.", completion = "No doubt you saw the Legion's warriors dotting the landscape on your flight from the Dark Portal. Though we defeated them at the Battle of Mount Hyjal some five years past, the cursed demons just keep coming back for more. If it's a challenge they crave, then the Horde will answer in kind!\n\nWe orcs have more than just a score to settle with the Legion. What about you, {name}? Shall I tell you of our enemy?", objectives = "Speak with Sergeant Shatterskull at the Supply Caravan just outside of Thrallmar, to the east.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10122] = { id = 10122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Citadel's Reach", description = "Each day, Hellfire Citadel opens its gates, and more fel orcs pour out and into the camps they've established along the ramparts south of the fortress.\n\nI dispatched one of my most capable scouts, Private Imarion, to track their movements, preparations and numbers, but he hasn't returned to report his findings.\n\nImarion was to focus his efforts on the northernmost camp along the Southern Rampart, near where it joined the Citadel. Find him, {name}. Without his information, we're sitting ducks.", sourceObjective = "Search the northernmost camp along the Southern Rampart for any trace of Private Imarion.", sourceObjectiveStatus = "unverified-source-field" }
quests[10123] = { id = 10123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felspark Ravine", description = "Doom Lord Kazzak commands the Burning Legion in Outland. While we can't get to Kazzak - yet - we can and must get to his lieutenants that command Legion troops from the ground.\n\nThey have stationed dreadlords in Felspark Ravine, east of here. They are responsible for these infernal storms that rain down upon our heads. To take them and their minions out would be a great set back to the Burning Legion.", progress = "Thrallmar is safe so long as the arcanist and his bloodmages remain at the front.", completion = "Outstanding work, soldier. The frequency of the attacks is sure to lessen - at least until they bring forth more dreadlords.\n\nNow for the bad news: I've got your new orders...", objectives = "Sergeant Shatterskull at the Supply Caravan east of Thrallmar in Hellfire Peninsula wants you to kill 4 Flamewaker Imps, 6 Infernal Warbringers and 1 Dreadcaller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10124] = { id = 10124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forward Base: Reaver's Fall", description = "Your battle prowess has been noted by high command, {class}. They want to send you to the front lines to meet up with Maimfist's crew. They're radicals, devoted to the complete extermination of the Burning Legion, so you may fit right in...\n\nHead east about 200 paces and veer south at the jutting mass of land. You'll see Reaver's Fall where an old farm used to stand. Once there, you are to report to Forward Commander To'arch.\n\nNow move out!", completion = "So you're the one responsible for clearing out Felspark, eh?  That's good to hear - we need soldiers like you who can take these fiends head on!", objectives = "Report to Forward Commander To'arch at Reaver's Fall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10125] = { id = 10125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Disrupt Communications", description = "Directly east of here is the Legion Front. The front acts as a mobile command station for the Burning Legion. Jutting out of the ground you'll see Legion antennas. The Legion uses these to communicate with their forge camps throughout Outland. They also serve as wards to scramble Legion transmissions, making magical surveillance impossible.\n\nI want you to take these explosives and use them to obliterate the antennas. Get all of them, {name}. They run south to north on the border of the Legion Front.", objectives = "Forward Commander To'arch at Reaver's Fall in Hellfire Peninsula has asked that you use To'arch's Explosives and destroy Legion Antenna: Spite, Legion Antenna: Rage, Legion Antenna: Hate, Legion Antenna: Fear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10126] = { id = 10126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warboss Nekrogg's Orders", description = "The orders, signed by 'Warboss Nekrogg,' order the fel orc patrols stationed at this camp to bring their human prisoner south for interrogation.\n\nLieutenant Amadi mentioned that the Southern Rampart is dotted with fel orc camps. Perhaps the next large section of the wall to the south is where they took Private Imarion.\n\nJudging by the note's mention of interrogation, it seems the private's fel orc captors see some value in keeping him alive. Pick up the trail before they decide to change their minds.", sourceObjective = "Travel south along the west side of the South Rampart and search the next camp for signs of Private Imarion.", sourceObjectiveStatus = "unverified-source-field" }
quests[10127] = { id = 10127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Sever the Tie", description = "It would be a dereliction of duty if I did not order you to take out the demons that inhabit the Legion Front, just east of this base.\n\nBoth sides of the front are set up in the same manner: Fel handlers roam between Legion encampments, which are in turn guarded by wrathguards. A shivan subjugator oversees the entire operation. Kill 'em all and let Kazzak sort 'em out.\n\nAnd watch out for patrolling fel reavers. I know you're tough but those things will make short work of you.", objectives = "Forward Commander To'arch at Reaver's Fall in Hellfire Peninsula wants you to kill 4 Fel Handlers, 8 Wrathguards, and Subjugator Shi'aziv.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10128] = { id = 10128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving Private Imarion", description = "The tracks lead south from Imarion's equipment, appearing to follow the Southern Rampart. The roughness of the shallow ruts suggests that Imarion's captors were in a hurry to move him to his next destination, but why?\n\nWas someone waiting there for him, perhaps the Warboss Nekrogg, the leader named in the orders you found further north?\n\nThe shield and the tracks raise more questions than they solve, but it seems certain that where you find Private Imarion, you're likely to find Warboss Nekrogg too.", sourceObjective = "Continue south along the Southern Rampart and search for where Warboss Nekrogg is holding Private Imarion.", sourceObjectiveStatus = "unverified-source-field" }
quests[10129] = { id = 10129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Gateways Murketh and Shaadraz", description = "We've identified the two main transporters that the Burning Legion are using to bring in reinforcements: Gateway Murketh and Gateway Shaadraz.\n\nIf you look east up the Path of Glory, you'll see them on either side of the road.  I want you to bomb them both into oblivion!\n\nHere are the bombs you'll use, specially designed by a goblin in Area 52.  Now, speak with Wing Commander Brack -- he'll put you on a wyvern.", progress = "If you missed during your first pass, take another...", completion = "That will set them back weeks! Fantastic work, {name}. The Legion never expected such heavy resistance.", objectives = "Speak with Wing Commander Brack, bomb Gateway Murketh and Gateway Shaadraz and then return to Forward Commander To'arch at Reaver's Fall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10130] = { id = 10130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Western Flank", description = "In addition to other instructions, the orders tell the remaining fel orcs to prepare their equipment and rations for a coming attack.\n\nAccording to the plans, Warboss Nekrogg's forces are to form the western flank of a pincer attack on Honor Hold.\n\nWith the hold's garrison concentrating on its eastern walls, an attack from the west would be devastating. Honor Hold can only hope to hold out if the western forces are kept out of the battle.", objectives = "Kill 10 Shattered Hand Guards, 10 Shattered Hand Berserkers, and 5 Shattered Hand Acolytes, then report to Lieutenant Amadi at Honor Hold's western guard tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10131] = { id = 10131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Planning the Escape", description = "Like I said, getting out of here won't be easy. Warboss Nekrogg may look like an overgrown brute, but he's no simpleton.\n\nHe won't let the cage key out of his sight and doesn't come down from his tower atop that chunk of wall until he's ready to question me or that orc he's managed to capture.\n\nIt's going to take something extraordinary to get him off that wall, but I have an idea. Find one of the grenadiers that patrol the ground along the Southern Rampart and bring me some of his explosives.", objectives = "Kill a Shattered Hand Grenadier and bring his Crude Explosives to Private Imarion at Gor'gaz Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10132] = { id = 10132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Colossal Menace", description = "You see that huge red crystal to the north?  It fell from the sky not long ago, causing a massive earthquake.\n\nWhen we came out here to investigate the disturbance, we found all of these colossi wandering about that weren't previously here.\n\nThere's definitely something strange about that crystal and the energies that it's emanating, but I don't have time for that.  Those mountain giants are my immediate concern.\n\nI want you to head up to Fallen Sky Ridge and deal with them.", completion = "Good work.\n\nIf you ask me, all that we have to do is kill enough of those colossi, and then we won't have to worry any longer about the ridge or that strange crystal in the middle of it.\n\nHere, take one of these as a gift from the Cenarion Expedition.", objectives = "Slay 5 Raging Colossi and then return to Tola'thion at the Cenarion Post in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10133] = { id = 10133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Kill the Messenger", description = "Your handiwork is already causing the Legion great discomfort, {name}. My scouts have just informed me that the Legion has resorted to sending communication via courier. We have successfully managed to cut their troops off from the host!\n\nWhat I ask of you next is more than I would ask of an ordinary soldier.\n\nThe Legion courier travels from the Pools of Aggonar to Forge Base: Mageddon, north of here. You must intercept the courier at Mageddon, dispose of him, and return to me with the Legion missive.", objectives = "Forward Commander To'arch at Reaver's Fall in Hellfire Peninsula has asked that you find and slay Arix'malidash and recover the Legion Missive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10134] = { id = 10134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crimson Crystal Clue", description = "As the colossus falls under the weight of your attacks, you notice for the first time that it was holding a red crystal fragment.\n\nWhile it was small and unnoticeable in the mountain giant's hand, it's a fairly hefty piece for you to carry around.  It also suspiciously looks like it's a piece of the giant crystal in the middle of the ridge.\n\nIt's most definitely a clue as to the strangeness that is occurring here, and you're sure that the druids at the Cenarion Post to the south will want to see it.", progress = "That's a big crystal you have there.  Did you get that while you were up at the ridge killing colossi?\n\nLet me take a look at it.", completion = "Hmph.  Just looks like a big lump of unrefined crystal to me.\n\nAdmittedly, I can feel a sickly, evil aura emanating off of it, but that's not exactly in my line of work.  I'm just here to put an end to the mountain giant menace.", objectives = "Deliver the Crimson Crystal Shard to Tola'thion at the Cenarion Post in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10135] = { id = 10135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Be the Messenger", description = "I am merely a field commander, {class}. The authority to act on this kind of information falls squarely on the shoulders of our leader, Nazgrel. You must take this missive to him in Thrallmar. Ride with the wind at your back, soldier. Let nothing prevent you from reaching Nazgrel!", objectives = "Take the Legion Missive to Nazgrel at Thrallmar in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10136] = { id = 10136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cruel's Intentions", description = "Magister Bloodhawk finally deciphered the Legion missive you found earlier. It turned out to be attack plans sent by one of Highlord Kazzak's lieutenants - Arazzius the Cruel. Apparently, Arazzius commands the Legion ground forces in Hellfire. The time has come to terminate his command, {name}. Terminate with extreme prejudice. \n\nHead west to the Pools of Aggonar and put an end to this so-called 'Legion lord'. Today, the Horde reclaims Hellfire Peninsula. Let the Legion be damned.", completion = "For generations to come, they will sing songs of this day, {name} - songs of your valor. I wish Thrall had been here to celebrate this victory with us. The Legion is undone - and Hellfire now belongs to the Horde once again! There may yet be hope for this ravaged world - and our peoples' place within it. \n\nLok'tar ogar!", objectives = "Kill Arazzius the Cruel, then return to Nazgrel in Thrallmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10137] = { id = 10137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Provoking the Warboss", description = "The plan succeeds or fails on how well these explosives are made...\n\nAs much as I'd hate to rely on anything made by an orc, it's my only real chance to get out of here. Take this and throw it against the banner hanging from the tower up there.\n\nOnce it explodes, Warboss Nekrogg won't be able to resist the chance to make an example of the troublemaker. Kill him, take the key, and then open my cage. Good luck, {name}.You will be able to choose one of these rewards:", objectives = "Use the Crude Explosives to create a disturbance and lure Warboss Nekrogg out of his tower. Kill him, obtain Nekrogg's Key, and use it to open Private Imarion's cage. Once you have freed Private Imarion, report to Lieutenant Amadi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10138] = { id = 10138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under Whose Orders?", description = "One thing is clear, {name}: we can't keep this up. The fel orcs have us surrounded and as quickly as we can kill them, several spring up to replace them. We can't hope to win this war huddled behind Honor Hold's shattered walls and counting the days until our deaths at the hands of the fel orcs or the Legion.\n\nYou've done a remarkable job of sparing us from the brunt of the fel orc attack, but now you must fight your way up the Path of Glory and learn who is orchestrating these attacks.", objectives = "Kill 20 Shattered Hand Grunts, 10 Shattered Hand Warlocks, and capture Drillmaster Zurok's Orders. Then, return to Lieutenant Amadi at Honor Hold's western guard tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10139] = { id = 10139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dispatching the Commander", description = "From what I can tell, Drillmaster Zurok served as the right hand of the fel orc leader in Hellfire Peninsula, Force-Commander Gorax.\n\nThis Gorax isn't your typical fel orc brute, though. I almost admire the way he managed to keep us on the defensive for so long.\n\nZurok's orders indicate that Gorax's command center is located at the end of the Path of Glory, near where the citadel's walls meet the Northern Rampart. There's no telling what to expect, {name}, but it would be wise to travel with allies.", objectives = "Slay Force-Commander Gorax and report to Lieutenant Amadi at Honor Hold's western tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10140] = { id = 10140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to Honor Hold", description = "When you're ready, I'll arrange a flight straight to Honor Hold.\n\nFrom there, speak with Marshal Isildor and give him Duron's report.  He'll be happy to see another recruit from the homelands, and I'm sure the information in that report is important stuff!", progress = "Thank the Light you made it here safely. Honor Hold needs all the seasoned warriors it can muster.", completion = "Our expedition to this forsaken, wreck of a world has almost ground to a halt, {name}. We encountered more resistance than we bargained for.\n\nAs if facing the Burning Legion again wasn't bad enough - there are horrors in this land unlike anything we've ever encountered.", objectives = "Take a flight to Honor Hold and deliver Duron's Report to Marshal Isildor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10141] = { id = 10141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legion Reborn", description = "While the Burning Legion invaded Azeroth, they were also at work here, in Outland.  We have tracked their movements over the years, but this latest activity, {class} - well, this is beyond anything we've seen.\n\nSeek out Sergeant Altumus near the eastern supply caravan. She has been monitoring the invaders and may have insights into their purpose.\n\nBe swift - and take care, {name} - the Burning Legion is not to be underestimated.", completion = "Force Commander Danath may have misunderstood my request for reinforcements. You look capable, but... I asked for a full sized battalion!\n\nYou see, we have a bit of a demon problem...", objectives = "Speak with Sergeant Altumus at the East Supply Caravan just outside of Honor Hold, to the east.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10142] = { id = 10142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of Anguish", description = "Doom Lord Kazzak commands the Burning Legion in Outland. While we can't get to Kazzak - yet - we can and must get to his lieutenants that command Legion troops from the ground.\n\nThey have stationed dreadlords at the Path of Anguish, east of here. They are the ones responsible for these infernal storms that rain down upon our heads. To take them and their minions out would be a great set back to the Burning Legion.", progress = "Honor Hold is safe so long as the archers guard our skies.", completion = "Outstanding work, soldier. The frequency of the attacks is sure to lessen - at least until they bring forth new dreadlords.\n\nNow for the bad news: I've got your new orders...", objectives = "Sergeant Altumus at the East Supply Caravan east of Honor Hold in Hellfire Peninsula wants you to kill 4 Flamewaker Imps, 6 Infernal Warbringers and 1 Dreadcaller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10143] = { id = 10143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expedition Point", description = "Your battle prowess has been noted by high command, {class}. They want to send you to the front lines to meet up with Rohamus's crew. They're radicals, devoted to the complete extermination of the Burning Legion, so you may fit right in...\n\nHead east about 400 paces, across the Valley of Bones, until you run into a destroyed fel reaver. You'll see Expedition Point where a Legion base used to stand. Once there, you are to report to Forward Commander Kingston.\n\nNow move out!", completion = "Glad to meet you, soldier.\n\nEnough chatting... now listen up -- I have a vital mission for you and I want you to succeed... and survive!", objectives = "Report to Forward Commander Kingston at Expedition Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10144] = { id = 10144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disrupt Their Reinforcements", description = "You'll find the Legion front to our northeast, and spaced along it are portals used to gather reinforcements from throughout Outland. We, {name}, are going to destroy those portals!\n\nTake this primer.  Designed in Area 52, it uses the demons' own power as an explosive device!  Defeat Legion forces around Portals Grimh and Kaalez to gather demonic rune stones, use the primer to detonate the stones inside the portals... then watch the fireworks!!\n\nGo, {name}, and return to me when your mission is complete.", progress = "I wish I could be there to watch the fire display.  Those explosives pack a big punch!", completion = "Well done, {name}.  Disabling those portals will stem the flow of Legion reinforcements for a long time!\n\nBut we can't rest yet...", objectives = "Defeat enemies around Portal Grimh and Portal Kaalez to gather Demonic Rune Stones.\n\nUse Kingston's Primer inside Portal Grimh and Portal Kaalez.\n\nReturn to Forward Commander Kingston with the remaining explosives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10146] = { id = 10146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: The Murketh and Shaadraz Gateways", description = "Just west of the Dark Portal are two huge transporters: Gateway Murketh and Gateway Shaadraz.\n\nIf you look east up the Path of Glory, you'll see them on either side of the road.  I want you to bomb them both into rubble!\n\nHere are the bombs you'll use, specially designed by a goblin in Area 52.  Now, speak with Wing Commander Dabir'ee -- he'll put you on a gryphon and send you on your way.", progress = "This is a vital mission, {name}.  It's one I would not trust to just anyone.", completion = "That will slow them down, there's no denying it! I think you just put me in an uncharacteristically good mood, {name}!", objectives = "Speak with Wing Commander Dabir'ee, bomb Gateway Murketh and Gateway Shaadraz and then return to Forward Commander Kingston at Expedition Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10147] = { id = 10147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Kill the Messenger", description = "Your handiwork is already causing the Legion great discomfort, {name}. My scouts have just informed me that the Legion has resorted to sending communication via courier. We have successfully managed to cut their troops off from the host!\n\nWhat I ask of you next is more than I would ask of an ordinary soldier.\n\nThe Legion courier travels from the Pools of Aggonar to Forge Base: Mageddon, far north of here. You must intercept the courier at Mageddon, dispose of him, and return to me with the Legion missive.", objectives = "Forward Commander Kingston at Expedition Point in Hellfire Peninsula has asked that you find and slay Arix'malidash and recover the Legion Missive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10148] = { id = 10148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Be the Messenger", description = "I am merely a field commander, {class}. The authority to act on this kind of information falls squarely on the shoulders of our leader, Force Commander Danath Trollbane. You must take this missive to him in Honor Hold. Ride with the wind at your back, soldier. Let nothing prevent you from reaching Danath!", objectives = "Take the Legion Missive to Force Commander Danath Trollbane at Honor Hold in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10149] = { id = 10149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: End All, Be All", description = "Do you know what would have happened if you had not intercepted this missive, {name}?\n\n<Danath nods.>\n\nThe entirety of the Legion army in Hellfire would have been knocking on our door. There is no way that we could have survived such an assault.\n\nThere is only one way to make sure that these orders never reach the Legion Front. You must travel to the Pools of Aggonar, far northwest of here, and slay this Arazzius creature.\n\nDo this and I will grant you a commendation.You will be able to choose one of these rewards:", objectives = "Force Commander Danath Trollbane at Honor Hold in Hellfire Peninsula has asked that you slay Arazzius the Cruel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10150] = { id = 10150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Citadel's Reach", description = "Each day, Hellfire Citadel opens its gates, and more fel orcs pour out and into the camps they've established along the ramparts south of the fortress.\n\nI dispatched one of my most capable trackers, Scout Makha, to track their movements, preparations and numbers, but she hasn't returned to report her findings.\n\nMakha was to focus her efforts on the northernmost camp along the Northern Rampart, near where it ends in the rocks. Find her, {name}. Without her information, we're sitting ducks.", sourceObjective = "Search the northernmost camp along the Northern Rampart for any trace of Scout Makha.", sourceObjectiveStatus = "unverified-source-field" }
quests[10151] = { id = 10151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warboss Nekrogg's Orders", description = "The orders, signed by 'Warboss Nekrogg,' order the fel orc patrols stationed at this camp to bring their orcish prisoner south for interrogation.\n\nShadow Hunter Ty'jin mentioned that the Northern Rampart is dotted with fel orc camps. Perhaps the next large section of the wall to the south is where they took Scout Makha.\n\nJudging by the note's mention of interrogation, it seems the scout's fel orc captors see some value in keeping her alive. Pick up the trail before they decide to change their minds.", sourceObjective = "Travel south along the west side of the Northern Rampart and search the next camp for signs of Scout Makha", sourceObjectiveStatus = "unverified-source-field" }
quests[10152] = { id = 10152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Western Flank", description = "In addition to other instructions, the orders tell the remaining fel orcs to prepare their equipment and rations for a coming attack.\n\nAccording to the plans, Warboss Nekrogg's forces are to form the western flank of a pincer attack on Thrallmar.\n\nWith the town's garrison concentrating on its eastern walls, an attack from the west would be devastating. Thrallmar can only hope to hold out if the western forces are kept out of the battle.", objectives = "Kill 10 Shattered Hand Guards, 10 Shattered Hand Berserkers, and 5 Shattered Hand Acolytes, then report to Stone Guard Ambelan at Spinebreaker Post near Zeth'Gor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10153] = { id = 10153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving Scout Makha", description = "The tracks lead south from Makha's equipment, appearing to cross the Path of Glory. The roughness of the shallow ruts suggests that Makha's captors were in a hurry to move her to the next destination, but why?\n\nWas someone waiting there for her, perhaps Warboss Nekrogg, the leader named in the orders you found further north?\n\nThe shield and the tracks raise more questions than they solve, but it seems certain that where you find Scout Makha, you're likely to find Warboss Nekrogg too.", sourceObjective = "Continue south across the Path of Glory to the Southern Rampart and search for where Warboss Nekrogg is holding Scout Makha.", sourceObjectiveStatus = "unverified-source-field" }
quests[10154] = { id = 10154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Planning the Escape", description = "Like I said, getting out of here won't be easy. Warboss Nekrogg may look like an overgrown brute, but he's no simpleton.\n\nHe won't let the cage key out of his sight and doesn't come down from his tower atop that chunk of wall until he's ready to question me or that human he's managed to capture.\n\nIt's going to take something extraordinary to get him off that wall, but I have an idea. Find one of the grenadiers that patrol the ground along the Southern Rampart and bring me some of his explosives.", objectives = "Kill a Shattered Hand Grenadier and bring his Crude Explosives to Scout Makha at Gor'gaz Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10155] = { id = 10155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Provoking the Warboss", description = "The plan succeeds or fails on how well these explosives are made...\n\nAs much as I'd hate to rely on anything made by a fel orc, it's my only real chance to get out of here. Take this and throw it against the banner hanging from the tower up there.\n\nOnce it explodes, Warboss Nekrogg won't be able to resist the chance to make an example of the troublemaker. Kill him, take the key, and then open my cage. Good luck, {name}.You will be able to choose one of these rewards:", objectives = "Use the Crude Explosives to create a disturbance and lure Warboss Nekrogg out of his tower. Kill him, obtain Nekrogg's Key, and use it to open Scout Makha's cage. Once you have freed Scout Makha, report to Stone Guard Ambelan at Spinebreaker Post near Zeth'Gor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10156] = { id = 10156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under Whose Orders?", description = "One thing is clear, {name}: we can't keep this up. The fel orcs have us pinned down and as quickly as we can kill them, several spring up to replace them. We can't hope to win this war with our forces divided and locked in constant combat with the fel orcs and the demons of the Legion.\n\nYou've done a remarkable job of blunting the fel orc attack, but now you must fight your way up the Path of Glory and learn who is orchestrating this offensive.", objectives = "Kill 20 Shattered Hand Grunts, 10 Shattered Hand Warlocks, and capture Drillmaster Zurok's Orders. Then, return to Stone Guard Ambelan at Spinebreaker Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10157] = { id = 10157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dispatching the Commander", description = "From what I can tell, Drillmaster Zurok served as the right hand of the fel orc leader in Hellfire Peninsula, Force-Commander Gorax.\n\nThis Gorax isn't your typical fel orc brute, though. I almost admire the way he managed to keep us on the defensive for so long.\n\nZurok's orders indicate that Gorax's command center is located at the end of the Path of Glory, near where the citadel's walls meet the Northern Rampart. There's no telling what to expect, {name}, but it would be wise to travel with allies.", objectives = "Slay Force-Commander Gorax and report to Shadow Hunter Ty'jin at Thrallmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10158] = { id = 10158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bleeding Hollow Supplies", description = "The orcish ruins of Zeth'Gor to serve as a base for an ever-growing tide of orcs emerging from Hellfire Citadel.\n\nShadow Hunter Ty'jin sent me here to keep an eye on the outpost and its strange inhabitants.\n\nSomething has changed these orcs, augmented them in a way we've never seen before. We have to do anything we can to keep them from strengthening. Fight your way into Zeth'Gor and destroy any supplies you find there.", objectives = "Destroy 6 piles of Bleeding Hollow Supplies and report to Stone Guard Ambelan at Spinebreaker Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10159] = { id = 10159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep Thornfang Hill Clear!", description = "We've been fighting an ongoing battle to keep the pass through Thornfang Hill to the west clear of ravagers.  It would be bad if we were to become completely cut off from the refuge in Zangarmarsh.\n\nWe don't want to displace the creatures, but there seems to be little choice as their attacks on travelers through the area have become more aggressive.\n\nClear some of the ravagers out of there if you can.", progress = "How fares your attempt to clear Thornfang Hill?", completion = "With the ravagers cleared, travelers to and from the Cenarion Refuge in Zangarmarsh should have an easier time of it.\n\nThe Cenarion Expedition is indebted to you.", objectives = "Kill 8 Thornfang Ravagers and 8 Thornfang Venomspitters, and then return to Mahuram Stouthoof at the Cenarion Post in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10160] = { id = 10160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Know your Enemy", description = "Rumors have surfaced that some new breed of orc is on the rise. Larger, meaner - more cunning than the brutes we're familiar with.  If these rumors are true then our forces, already stretched, may be taxed beyond their limit.\n\nI have entrusted my lieutenant, Amadi, with investigating this matter. If you would help us in this dark hour, seek her out. She is stationed at the broken tower just west of the Hold.\n\nAnd {name} - be careful out there. You're heading into a dangerous new world.", completion = "<Lieutenant Amadi nods.>\n\nGood, we need all the help we can get. The increasing fel orc presence around the Southern Rampart concerns me. I sent out a scout to investigate, but he hasn't yet returned.", objectives = "Speak with Lieutenant Amadi at the old guard tower just west of Honor Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10161] = { id = 10161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Case of Emergency...", description = "In the event of an emergency, it's always the pilot's job to keep a level head, especially when the only orders your co-pilot follows come from his stomach.\n\nThe good news is that we won't need to wait days for replacement parts to be imported. The bad news is that the \"spare\" parts got scattered from here to the Valley of Bones to the east.\n\nThe other bad news? The spare parts aren't so spare. They, uh, fell off during our rapid descent. Could you help me collect enough to get us off the ground again?", progress = "Did you find enough of the parts? If not, I might have to use that frying pan Legassi keeps waving around. Then, I'd have to rename the zeppelin the \"Flying Skillet.\"", completion = "Some of this is in pretty bad shape, but there should be enough to work with here. With some creative engineering, I'm confident I can make it work!", objectives = "Collect 30 pieces of Zeppelin Debris and bring them to \"Screaming\" Screed Luckheed at the Zeppelin Crash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10162] = { id = 10162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: The Abyssal Shelf", description = "Now that you've got your wings, perhaps you'd be interested in running another bombing mission?\n\nThis time we've isolated the Legion's main production area, behind the forge camps to the north. I need you to get on a wyvern and destroy the whole damned thing!\n\nHere are your bombs - now, talk to Wing Commander Brack when you're ready for takeoff.", progress = "Show them that not even the skies are safe!", completion = "You fly as if you've been doing this your entire life, {name}. Outstanding performance out there! Not even a scratch on the wyvern destroyers!", objectives = "Forward Commander To'arch at Reaver's Fall in Hellfire Peninsula has asked that you destroy 20 Gan'arg Peons, 5 Mo'arg Overseers and 5 Fel Cannons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10163] = { id = 10163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: The Abyssal Shelf", description = "Now that you've got your wings, perhaps you'd be interested in running another bombing mission?\n\nThis time we've isolated the Legion's main production area, behind the forge camps to the north. I need you to get on a gryphon and destroy the whole damned thing!\n\nHere are your bombs - now, talk to Gryphoneer Windbellow when you're ready for takeoff.", progress = "Show them that not even the skies are safe!", completion = "You fly as if you've been doing this your entire life, {name}. Outstanding performance out there! Not even a scratch on the gryphon destroyers!", objectives = "Wing Commander Gryphongar at Shatter Point in Hellfire Peninsula has asked that you destroy 20 Gan'arg Peons, 5 Mo'arg Overseers and 5 Fel Cannons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10164] = { id = 10164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everything Will Be Alright", description = "You've had quite an adventure, {name}. And before you've even set foot inside of the Auchenai Crypts.\n\nI am one of the fortunate spirits. I was neither bound to Levixus nor a part of Exarch Maladaar's vile experiments in necromancy. While you have destroyed Levixus, Maladaar lives on, continuing to torment the spirits inside the crypts.\n\nWhat I ask is simple. Enter the Auchenai Crypts and destroy Exarch Maladaar so that the spirits trapped inside can finally rest in peace.", completion = "You've done it, {name}! The spirits are freed!\n\nAlthough I am without a material manifestation, I am still able to reward you with items from the spirit world. Use them with caution as such items are often volatile and can cause great harm to their user.", objectives = "Greatfather Aldrimus standing outside the Auchenai Crypts of Auchindoun has asked that you enter the Auchenai Crypts and destroy Exarch Maladaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10165] = { id = 10165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undercutting the Competition", description = "That Shaffar is a shrewd one - I'll give him that... He's managed to keep the Consortium out while he safely pillages this crypt for all it's worth. I have no faith in these imbeciles actually breaking through Shaffar's defenses so I'll make you a deal, {race}.\n\nEnter the Mana-Tombs and kill Nexus-Prince Shaffar. Bring me back his body wrap as proof of this deed and I'll reward you handsomely.", progress = "I don't like to \"share.\"", completion = "Another competitor goes under... You do good work for a flesh beast, {race}. If you are ever in Netherstorm, look me up. I make my home at the Stormspire.", objectives = "Nexus-Prince Haramad located outside of the Mana-Tombs wants you to kill Nexus-Prince Shaffar and bring Shaffar's Wrappings back to him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10166] = { id = 10166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whitebark's Memory", description = "This pendant brings back memories of a different time.  A better time.\n\nUnfortunately, memories are the last thing I need right now.\n\nI want you to bury this by the runestone in the Scorched Grove.  It was there that I first met the treant elder.  Put my old friend's memory to rest.", progress = "You've returned, {name}.  Haven't you done enough?", completion = "I no longer belong to this world and must admit defeat.  The land has forever changed and nothing will ever be the same.\n\nLeave the pendant here with me, {name}.  Maybe one day, long after the elves are gone, a new tree will grow on this very spot - amongst a burnt forest and the husks of dead treants.", objectives = "Larianna Riverwind wants you to place Old Whitebark's Pendant by the runestone at the Scorched Grove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10167] = { id = 10167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auchindoun...", description = "Deep within the Auchenai Crypts is a tomb: A tomb unlike any that exists on this shattered realm. It was from this tomb, the first tomb, that the vast mausoleum of Auchindoun was born.\n\nYou must venture to the Auchenai Crypts of Auchindoun and find this tomb. Slay the guardian of the crypt to release the captive spirit within. The spirit holds the key...", completion = "The memory is vivid, {name}. My energies were wholly drained from the crash. I was only a dim speck of void energies when the Prophet Velen and his draenei compatriots lifted my remains and brought them here. After much ceremony, my diminished form was laid to rest within this sarcophagus. I have been regenerating for nearly a thousand years. The cycle is almost complete...", objectives = "Travel to the Auchenai Crypts in the Bone Wastes of Terokkar Forest and slay Exarch Maladaar to free the spirit of D'ore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10168] = { id = 10168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What the Soul Sees", description = "For several centuries, the spirits of Auchindoun coalesced into my darkened essence. Many of the catastrophes that befell this crypt were a direct result of my weakened state.\n\nRegrettably, there is nothing that can be done to stop this cycle. It is a facet of the naaru condition - without the void, the Light cannot exist.\n\nYour only recourse is to destroy the ancient spirits of Nagrand before they transform into creatures of the void. Use the soul mirrors found throughout this crypt to free them...", progress = "<Mother Kashur is visibly upset.>\n\nThese naaru are wise beyond all manner of life on this world.", completion = "You have completed a long and dangerous journey, risking life and limb to ensure the safety of the Mag'har and the serenity of our ancestors. For this I am thankful beyond what words could convey.", objectives = "Locate a Soul Mirror somewhere in the Auchenai Crypts and use it to call forth a Darkened Spirit from Ancient Orc Ancestors in Nagrand. Destroy 15 Darkened Spirits so that the ancestors may rest in peace.\n\nReturn to Mother Kashur at the Ancestral Grounds when this task is complete.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10169] = { id = 10169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Losing Gracefully", description = "The Aldor have gained the favor of the Sha'tar today.  As if that should come as any sort of surprise!\n\nWatch them showing off their fancy footwork a few feet away from A'dal.  Could they possibly put any more effort into sucking up to the naaru?\n\nHarbinger Haronem's marksman regiment is so dedicated, it even brings its own cooking pot to avoid taking long breaks for lunch.  This cannot go without retribution, {name}.\n\nI want you to pour this vial into their meal.  The results should be... comical.", objectives = "Magister Falris in Shattrath wants you to take the Vial of Sedative Serum to the Terrace of Light and pour it into Haronem's Regiment Cooking Pot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10170] = { id = 10170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Greatmother", description = "Return to Greatmother Geyah at Garadar with news of your victory, {name}. This will surely lift the spirits of the Mag'har. Perhaps even the young Hellscream will be lifted from his malaise.", completion = "I want you to personally deliver this news to Garrosh.", objectives = "Return to Garadar and speak to Greatmother Geyah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10171] = { id = 10171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Inconsolable Chieftain", description = "You have done so much for the Mag'har, {name}. Your accomplishments are known to all, including Garrosh. Go to him now and tell him of your latest victory. Tell him that you do what you do for him and his people. Surely he will be lifted by your words.", completion = "Everyone is proud. Proud that our people will live to see another winter. But beyond that? What is there?\n\nMaybe you should lead this clan, {name}. Maybe then I will be allowed to die when the Greatmother passes. Allowed to finally erase the shame of my family name. I long for such peace.", objectives = "Greatmother Geyah at Garadar has asked that you speak with Garrosh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10172] = { id = 10172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There Is No Hope", description = "You are an honorable {race}, {name}. You have done much for the Mag'har. No one could ever deny your service to my people. Alas, the time of the Mag'har is at an end. You have shown me, more than anything, that I am unfit to lead these people. My cursed blood runs too deep. I will not... I cannot become the second Hellscream to damn the orcs.\n\nPlease, {name}, return to the Greatmother and tell her what I have told you. I am too ashamed to see her... to look into her eyes.", completion = "<Tears stream down Greatmother Geyah's face.>\n\nThrall is coming.  I know he will be here soon.", objectives = "Speak to Greatmother Geyah and tell her what Garrosh told you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10173] = { id = 10173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Archmage's Staff", description = "Allow me to introduce myself, {class}.\n\nI am Ravandwyr, apprentice to the Archmage Vargoth.\n\nMy master is... indisposed, shall we say. I am here on a matter of great importance.\n\nThe Arklon Ruins southeast of the city are a hotbed of Burning Legion activity. Their purpose in the ruins concerns neither me nor my master, but their leader, Ekkorash, possesses the archmage's staff.\n\nThis conjuring powder will allow you to draw the demon out of hiding. Sprinkle it on the brazier at the center of the ruins.", progress = "I will not rest until Archmage Vargoth's staff is restored to him. Were you able to wrest it from the demon's grasp?", completion = "Ah, so you managed to recover the staff. Impressive, {name}. Perhaps you are the one I've been looking for.\n\nOh yes, your reward...\n\n\n\nNo doubt you had higher expectations, but that too will come with time. For now, consider opportunity the true reward.", objectives = "Retrieve Archmage Vargoth's Staff from Ekkorash the Inquisitor and bring it to Ravandwyr in Area 52. To bring Ekkorash out of hiding, sprinkle the Conjuring Powder on the brazier in the center of the ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10174] = { id = 10174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curse of the Violet Tower", description = "Now, you will be able to use the archmage's staff to contact him.\n\nHe resides in the Violet Tower, on an 'island' to the southeast. The tower is both sanctuary and prison to him, cursed as it is. Kirin Tor can neither enter nor leave, keeping me apart from my master.\n\nThe staff's magic can penetrate the tower's defenses, but only if invoked by one outside the Kirin Tor.\n\nTake the archmage's staff and use it to conjure his image. Tell him what has happened and that I have not completely failed him.", completion = "<Archmage Vargoth's image examines you as you convey Ravandwyr's message.>\n\nRavandwyr has everything a master can expect of his apprentice. When I gave him the staff and told him to flee, I hoped that he would use it to find help and free me once Kael'thas's forces withdrew from the tower. Since then, I have learned a great deal about the nature of the curse.\n\nIt can be broken, {name}, but it will require your help.", objectives = "Use Archmage Vargoth's Staff to make contact with Archmage Vargoth.\n\nIf you lose Archmage Vargoth's Staff, speak to Ravandwyr at Area 52 to receive a replacement.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10175] = { id = 10175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thrall, Son of Durotan", description = "Return to your world, {name}. Go to my grandchild and tell him that his blood is here - on this shattered world.\n\nTell him that his father's legacy lives on.\n\nTell him everything...", sourceObjective = "Venture to Orgrimmar and deliver Geyah's message to Thrall.", sourceObjectiveStatus = "unverified-source-field" }
quests[10176] = { id = 10176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ar'kelos the Guardian", description = "Now that you've gathered all the items I'll need to break Kael'thas's curse, one thing remains to be done. When Kael'thas sealed the tower, he placed an arcane golem, known as Ar'kelos, at the bottom of the tower.\n\nYou must defeat Ar'kelos in order allow me to work magic within the tower again.\n\nWhen you enter the Violet Tower, the curse will begin to affect you.\n\nOnce you have defeated Ar'kelos, ascend the tower and assist me in making preparations for the ritual.", completion = "You have done well, {name}. Destroying the dampening field will make it much easier for me to prepare the magic that will lift the tower's curse at last.", objectives = "Enter the Violet Tower at the center of Kirin'Var Village and defeat Ar'kelos, then speak with Archmage Vargoth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10177] = { id = 10177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at Auchindoun", description = "I have spies within Auchindoun and they have been sending me disturbing reports.  That place has been nothing but trouble ever since it exploded a couple of years ago.\n\nSomething in there has gone horribly wrong - again - and the Shadow Council is now on a war footing.  Though the reports were lacking on details, their preparations appear to be directed inward.\n\nYou must make your way to the entrance of the Shadow Labyrinth.  My field commander, Mahfuun, will fill you in on what needs to be done.", completion = "It's about time that you arrived.\n\nMehlisah said that she would be sending help days ago.  And we've been fighting in here longer than that!", objectives = "Report to Field Commander Mahfuun at the entrance to the Shadow Labyrinth at Auchindoun in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10178] = { id = 10178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Spy To'gun", description = "To'gun, the fool!  We're barely holding off the attacks here, and he goes back in to get more information and try to save the other spies!\n\nI don't know whether to love him or kill him!\n\nThe Shadow Council must have used magic to ferret us out, because all of our spies had to get out of there in a hurry.  Most of us didn't make it.\n\nPlease, if you're brave enough to enter the Shadow Labyrinth, will you keep an eye peeled for To'gun?  It's been a while, and I fear the worst.", completion = "What?  Grik'tha sent you in here after me?\n\nI don't know whether to be touched or call her a fool!\n\nDo you think you could help me get out of this cage?  It's a bit cramped.", objectives = "Locate Spy To'gun in the Shadow Labyrinth of Auchindoun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10179] = { id = 10179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Custodian of Kirin'Var", description = "When it became clear that our expedition was trapped in Outland with no way to return to Azeroth, the Kirin Tor contingent traveled to the Plains of Farahlon and built Kirin'Var village. I left the administration of the town in the hands of Custodian Dieworth, but when Kael'thas and his forces sealed me in the Violet Tower, I lost contact with the custodian.\n\nSearch for him in Kirin'Var Village and help him in any way you can, {name}. I'm certain he's got his hands full in the aftermath of the attack.", sourceObjective = "Speak with Custodian Dierworth at Kirin'Var Village in Netherstorm.", sourceObjectiveStatus = "unverified-source-field" }
quests[10180] = { id = 10180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can't Stay Away", description = "I tried to persuade Isfar to remain here, in the safety of Shattrath, but he would have none of it. Instead, he's decided to venture out to Auchindoun again on his own.\n\nHe was lucky enough to escape the Sethekk Halls once, but if they discover him, there won't be a second time.\n\nI admire his desire to free his sister, but he's not going to be able to do it without help.\n\nFind Isfar and have a word with him, {name}. If you can't persuade him to come back, perhaps you could help him rescue Lakka?", completion = "I should've suspected he would send you after me. He tried to talk me out of returning to the Sethekk Halls, but I couldn't live with myself if I allowed Lakka to die in there.", objectives = "Speak with Isfar, who can be found just inside the Sethekk Halls in Auchindoun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10181] = { id = 10181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Collector's Edition: -pn - E - FLAG" }
quests[10182] = { id = 10182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle-Mage Dathric", description = "The sword is of exceptional quality, finely crafted and perfectly balanced for a battle-mage. The seal of the Kirin Tor and the name \"Dathric\" are engraved into the weapon's pommel.\n\nTurning the weapon over in your hands, you notice a sense of wrongness radiating from the metal, as if the item is torn between two worlds. Could this be the item anchoring Battle-Mage Dathric's spirit to this world?\n\nPerhaps returning it to its proper place can break the bond, freeing Dathric's spirit to rest at last.", progress = "What have you found, {name}?", completion = "You've done well, {name}. I can no longer sense any restlessness in Dathric's spirit. I would give much for the opportunity to speak to him one more time, but it is enough that he is finally at rest.", objectives = "Locate Battle-Mage Dathric's quarters in Wizard's Row and return the blade to his weapon rack. Then, speak with Custodian Dieworth at Kirin'Var Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10183] = { id = 10183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Off To Area 52", description = "I'm out here studying the nether - the ethereal currents and all that.  This is an ideal spot away from the lights and hubbub of town.  Isn't this bridge great?  If I could just keep this junk working.\n\nHey, you know, if you're looking for work there's plenty at Area 52!  It's just up the path and take a right at the fork in the road.\n\nWhy don't you deliver my latest research notes to Rocket-Chief Fuselage?  I'm sure that he'd have plenty for you to do, what with the X-52 rocket ship, and all!", progress = "Busy, busy.  No time to waste!  There's a rocket ship to be built!\n\nWhat do you want?", completion = "Oh, Coppernickels finally decided to report his findings, did he?  Lazy scientists!\n\nWhat's this?\n\n<The chief riffles through the notations a few times, clearly with a look of disbelief.>\n\nHe says here that the violent nether-energies flowing through the Netherstorm are going to rip everything to shreds in only a few months.\n\nThat's inconvenient - now we'll have to move up the time-table on building the rocket ship!", objectives = "Deliver the Netherologist's Notes to Rocket-Chief Fuselage at Area 52 in the Netherstorm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10184] = { id = 10184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malevolent Remnants", description = "Most of the spirits in the village are little more than pale remnants of Kirin Tor mages. They retain no knowledge of their former selves and wander the ruins in blind anger.\n\nIt wasn't always like this, though. In the immediate aftermath of the attack, the spirits were restless, but not spiteful. With the passage of time they have only grown more aggressive. I dare not venture into the southern part of the village, for they will not spare even me. Quiet them and let us hope it will purge their anger.", completion = "<Custodian Dieworth shakes his head gently.>\n\nIt is not what they deserved, but it is the best we can do.", objectives = "Custodian Dieworth at Kirin'Var Village wants you to defeat 20 Severed Spirits in Kirin'Var's Town Square.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10185] = { id = 10185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fate Worse Than Death", description = "After the blood elves leveled Kirin'Var Village, they started the construction of a large building to the northwest. Without the expertise of the archmage, we can't say for certain what's going on there.\n\nOne thing is clear, though. The blood elf activities have unleashed a tide of ravenous mana elementals on the village. They seem drawn to the ruins of Wizard Row, wreaking further destruction. We cannot permit this to continue.", completion = "<The custodian looks dismayed.>\n\nI can already see the next wave coming over the horizon. Culling them will work for the time being, but more permanent measures are needed.", objectives = "Kill 10 Mageslayers and 10 Mana Seekers and return to Custodian Dieworth at Kirin'Var Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10186] = { id = 10186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You're Hired!", description = "Let me be the first to welcome you aboard, Junior Technician 3rd Grade {name}!\n\nWe're building my masterpiece out here - the X-52 Nether-Rocket!\n\nBut first we need to get all of the parts and fuel for it.  That's where you come in.\n\nTo start, I need crystals - LOTS of crystals - for the rocket's Etherlithium Engine Matrix.  The draenei had crystals coming out of their ears!\n\nSo head north to the Ruins of Enkaat and get them for me!  Nevermind all of the draenei ghosts.", progress = "Does it look like the X-52 Nether-Rocket is ready for liftoff?  Am I cruising the Twisting Nether in the comfort of my command chair?  Exploiting strange new worlds?  Seeking out new technology and business opportunities?  Boldly going where no goblin has gone before?\n\nNo!\n\nSo, I hope you have those crystals that I sent you after.", completion = "Gah!  Those look rough.  Maybe we can use them in the tertiary engine manifold chamber?\n\nStill, a good job Junior Technician 3rd Grade!  You'll make 2nd Grade in no time.", objectives = "Collect 10 Etherlithium Matrix Crystals and return them to Rocket-Chief Fuselage at Area 52 in the Netherstorm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10187] = { id = 10187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Message for the Archmage", description = "Although things are grim here, it heartened us quite a bit to hear from you that the archmage has not forgotten the village's plight.\n\n<The custodian glances up at the tower.>\n\nIt's ridiculous, isn't it? Sometimes it seems all that separates us is a wall of mere stone. The wall of magic is easy enough to forget.\n\nIf you would be so kind, ascend the tower and let Archmage Vargoth know that we are making progress with the village and will soon have a plan to ward off the mana creatures.", sourceObjective = "Speak to Archmage Vargoth at the top of the Violet Tower in Netherstorm.", sourceObjectiveStatus = "unverified-source-field" }
quests[10188] = { id = 10188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sigil of Krasus", description = "Before we departed Azeroth all those years ago, the Kirin Tor entrusted our expedition with a powerful artifact, the Sigil of Krasus. It was a great boon to us in our battle against the orcs and it could play a key role in helping me break the enchantment that imprisons me.\n\nHowever, when Kael'thas divested me of my possessions, he gave the sigil to Spellbinder Maryana, who remained behind with the garrison. If he truly realized what he had in his possession, he wouldn't have given it away so easily.", progress = "If I am to be free of the tower's curse, I must have the sigil.", completion = "Ah, it is as magnificent as I remembered. Can you not feel the power radiating from it?\n\nOf course, there is much more to be done, but you have my deepest thanks for restoring the sigil to me.", objectives = "Retrieve the Sigil of Krasus from Spellbinder Maryana at Manaforge Coruu, northwest of the Violet Tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10189] = { id = 10189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaforge B'naar", description = "You may have noticed one of Kael's manaforges on your way here.  You know, the large purple buildings sucking energy from the sky?\n\nWe were sent here by the Sha'tar to investigate them.  You can help our information gathering efforts by obtaining a personnel roster.  Giving us an idea of who's there and what they do will prove to be invaluable information.\n\nWe believe Captain Arathyn, leading a ballista team just outside of Manaforge B'naar, is in possession of one such roster.  Obtain it for us.", progress = "Did you obtain the items I asked of you, {name}?", completion = "Excellent!  With this roster we can make more educated decisions when targeting Kael's followers at the manaforges.\n\nIt's too bad, I was beginning to take a liking to killing his lackeys indiscriminately.", objectives = "Spymaster Thalodien at Area 52 wants you to go to the outskirts of Manaforge B'naar and retrieve the B'naar Personnel Roster from Captain Arathyn.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10190] = { id = 10190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recharging the Batteries", description = "I have the very important task of collecting the machinery inside these ruins, but I'm having a problem keeping all of my bots charged up.\n\nThe phase hunters - those wyrm-looking things - have lots of energy!  You can find them all over the edges of this island, floating in from the nether.\n\nFill the battery on this recharging blaster by using it on a phase hunter when they're very weak, and then finish it off to soak up the last of its energy.", progress = "Have you recharged the battery in that blaster yet?", completion = "Hey, watch where you're pointing that thing!  You've got it set to 'Kill'!!!\n\nIt looks like you've recharged the battery, and then some.  This'll help immensely to keep these guys going.", objectives = "Use the Battery Recharging Blaster on enough Phase Hunters to get the Battery Recharge Level to 10. Then return it to Bot-Specialist Alley at the Ruins of Enkaat in the Netherstorm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10191] = { id = 10191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mark V is Alive!", description = "Greetings, {race}.  I am charged up and fully functional.\n\nThere are fragile draenei machines in these ruins, which I must retrieve.  I am equipped with delicate servos in my wrist actuators, and the latest in combustion-pneumatic bump soakers.  Handling them with care will not be an issue.\n\nHowever, the ghosts that haunt these ruins will likely attack, so I will need you and your friends along for protection.", progress = "Back so soon?\n\nIs everything okay with the Maxx A. Million Mk. V?!", completion = "You did it!  You did it!  I could just kiss you!\n\nOh, darn... the Maxx A. Million Mk. V is out of juice again.  Ah well, he had enough to get the job done, and that's what counts!\n\nRocket-Chief Fuselage will be pleased to get these draenei machines hooked up inside the X-52 Nether-Rocket!  That means a promotion for me!  I'm so happy, I just have to give you a reward!\n\nHere, take your pick from one of these.", objectives = "Escort the Maxx A. Million Mk. V through the Ruins of Enkaat and back out to safety. Then speak with Bot-Specialist Alley just outside the Ruins of Enkaat in the Netherstorm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10192] = { id = 10192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krasus's Compendium", description = "The Kirin Tor sent one other of Krasus's possessions with our expedition. It was his spellbook, called Krasus's Compendium. Containing all the spells he mastered, it lent us a much-needed advantage in the war.\n\nBefore Kael'thas and his forces laid siege to Kirin'Var, the compendium had been stolen from me by a rebellious apprentice intent on studying necromancy. The apprentice and his followers divided and studied the text in secret, locking themselves inside their houses in the southern part of town.", progress = "Have you brought the book?", completion = "<Archmage Vargoth's image seems to inspect the compendium.>\n\nIt's a little worse for the wear, but considering the treatment it's been through, it's a miracle all of it survived. Safeguard it, {name}. Without it, we stand little chance of being able to break the tower's ward.", objectives = "Reclaim Krasus's Compendium - Chapter 1, Krasus's Compendium - Chapter 2, and Krasus's Compendium - Chapter 3 from Kirin'Var Village's Town Square.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
